local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["zone:shadowfang"] = {n="Bastilha da Presa Negra",s="Erguida sobre os penhascos escarpados acima do Vilarejo Lenhardente, a Bastilha da Presa Negra é a sombria fortaleza do mago renegado do Kirin Tor, o Arquimago Arugal. Outrora a propriedade ancestral do Barão Silverlaine, o bastião agora fervilha de feras worgens ferozes e dos fantasmas atormentados de seus defensores massacrados. Para os aventureiros que cruzam o sul de Pinhaprata, a bastilha representa o epicentro sombrio do flagelo bestial que consome a região.",h="Erguida sobre os penhascos escarpados acima do Vilarejo Lenhardente, a Bastilha da Presa Negra é a sombria...",kw={"arugal","fenrus","vilarejo lenhardente","sfk","bastilha da presa negra","silverlaine","floresta de pinhaprata","comandante floraval","worgen"},ang={["class:Mage"]="A tragédia de Presa Negra serve como um aviso sombrio sobre o que acontece quando um mago do Kirin Tor se intromete em invocações extradimensionais além do controle mortal.",["class:Paladin"]="O espírito inquieto do Comandante Floraval permanece como uma dolorosa lembrança dos defensores caídos do Punho de Prata, cujos juramentos sagrados foram deturpados pela morte.",["class:Warlock"]="As energias sombrias, os emissários do caos e as feitiçarias vis dentro da bastilha atraem o interesse de praticantes que buscam recuperar relíquias antigas como O orbe de Soran'ruk.",["faction:Horde"]="Os Renegados veem as alcateias crescentes de Arugal como um perigo imediato para seu território recém-estabelecido em Pinhaprata, tornando a bastilha um alvo prioritário para os agentes Deathstalker e para a Real Sociedade de Boticários."},sec={{t="A Queda da Dinastia Silverlaine",b="Antes de ser envolta em pesadelo, Presa Negra era conhecida como Silverlaine Keep, uma sede nobre leal aos senhores guilneanos e guarnecida pelo piedoso Comandante Floraval. Quando o Flagelo varreu Lordaeron durante a Terceira Guerra, os magos de Dalaran caíram em massa. Desesperado para conter a maré de mortos-vivos, o Arquimago Arugal desafiou a liderança do Kirin Tor e mergulhou nas pesquisas do mago Ur, invocando worgens extradimensionais para virar o jogo. As feras invocadas estraçalharam os mortos-vivos, mas rapidamente fugiram a qualquer controle mortal, invadindo o sul de Pinhaprata e tomando o bastião de assalto. O Barão Silverlaine e toda a sua corte foram massacrados, condenados a assombrar os salões de pedra ao lado dos monstros ferozes que subjugaram seu lar."},{t="Os Filhos de Arugal",b="Quebrado pela culpa e pela loucura, Arugal recuou para dentro das muralhas manchadas de sangue, adotando os vorazes homens-lobo como seus amados 'filhos' e rebatizando o castelo de Bastilha da Presa Negra. No fundo dos poleiros de pedra, alcateias lupinas e cães sombrios prosperam sob o comando de adestradores como Wolf Master Nandos, vigiados pela colossal besta lupina de Arugal, Fenrus, o Devorador. Fora das muralhas, a maldição não cessou; o vizinho Vilarejo Lenhardente permanece preso a um aterrorizante ciclo noturno, com seus moradores vivendo como homens de dia e caçando como worgens vorazes sob o luar, inexoravelmente atados ao arquimago louco empoleirado nas alturas."},{t="O Ataque dos Renegados",b="Reconhecendo a terrível ameaça que Arugal representa para seu domínio na Floresta de Pinhaprata, Grande Dama Sylvana Correventos despachou a Real Sociedade de Boticários e os letais Deathstalkers de elite para erradicar a fonte da maldição dos worgens. As equipes de infiltração sofreram baixas brutais dentro das masmorras, mas os heróis da Horda que atendem ao chamado d'O Sepulcro finalmente invadem a torre mais alta. Abater o Arquimago decreta o fim oficial do mestre da alcateia, quebrando a mente que orquestrava a proliferação das feras pela natureza e tomando sua cabeça como prova da vingança de Lordaeron."}},faq={{q="O que acontece quando o Arquimago Arugal é derrotado?",a="Matar Arugal decapita a força central que comanda as alcateias de worgens no sul de Pinhaprata. Aventureiros da Horda entregam sua cabeça decepada a Dalar Tessalba n'O Sepulcro, sob ordens de Grande Dama Sylvana Correventos. Embora sua morte quebre a vontade direta que controlava a alcateia de Presa Negra, as feras selvagens e os restos fantasmagóricos que vagam pela bastilha e pelos bosques circundantes continuam sendo um perigo constante para os viajantes.",al={"desfecho da morte de arugal","história de arugal morto","o que acontece após a morte de arugal"}},{q="Por que Arugal invocou os worgens?",a="Durante a Terceira Guerra, os exércitos de Dalaran sofriam derrotas desastrosas contra o Flagelo. Magos caídos eram erguidos continuamente como soldados mortos-vivos do Lich Rei. Em busca de uma arma para mudar o rumo da batalha, Arugal usou as pesquisas arcanas do mago Ur para invocar worgens extradimensionais, acreditando que sua ferocidade deteria o Flagelo.",al={"por que os worgens foram invocados","motivação de arugal","invocação de worgens em dalaran"}},{q="Quem foi o Barão Silverlaine?",a="O Barão Silverlaine foi o nobre humano que governou a bastilha e administrou o vilarejo vizinho de Lenhardente antes da Terceira Guerra. Quando as feras invocadas por Arugal escaparam do controle, elas atacaram a fortaleza e massacraram o barão, sua corte e seus guardas. O fantasma vingativo de Silverlaine ainda assombra os grandes salões de jantar, amaldiçoado a vagar ao lado dos monstros que o assassinaram.",al={"história do barão silverlaine","antigo senhor de presa negra"}},{q="Por que os aldeões do Vilarejo Lenhardente são amigáveis durante o dia?",a="Arugal submeteu os habitantes do vizinho Vilarejo Lenhardente à sua magia sombria. Durante o dia, eles mantêm sua forma humana, sua consciência e um comportamento pacífico com viajantes da Aliança. Ao pôr do sol, a maldição se manifesta, transformando toda a população em worgens selvagens e leais ao arquimago louco da bastilha.",al={"humanos de lenhardente","maldição de lenhardente","por que lenhardente vira worgen"}},{q="Quem é o Comandante Floraval?",a="O Comandante Floraval foi um paladino do Punho de Prata e o oficial militar responsável por defender Silverlaine Keep. Quando os worgens tomaram a fortaleza, ele lutou até a morte. Seu espírito inquieto ainda patrulha os corredores superiores, apegando-se ao dever militar mesmo na morte-vida.",al={"história de floraval","chefe paladino fantasma"}},{q="O que é O Livro de Ur?",a="O Livro de Ur é um tomo contendo as pesquisas de Ur, um arquimago de Dalaran que estudou entidades extradimensionais, incluindo os worgens. Arugal usou os escritos de Ur para realizar suas invocações desastrosas. A Real Sociedade de Boticários na Cidade Baixa busca o livro para entender a natureza das criaturas-lobo e de sua magia bizarra.",al={"missão do livro de ur","história de ur"}}},fp="15,425,31.728.0,17.630.0,19.576.1,46.419.1,33.338.0,26.378.0,59.299.0,28.282.0,23.334.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Shen'dralas é uma região selvagem, acidentada e disputada, situada entre Feralas, Mulgore e o sudeste de Desolação. Dominada por antigos vestígios élficos noturnos e fronteiras conturbadas, ela serve como uma encruzilhada volátil onde centauros invasores, proscritos deslocados e javatuscos hostis colidem.",h="Shen'dralas é uma região selvagem, acidentada e disputada, situada entre Feralas, Mulgore e o sudeste de...",kw={"refúgio dos costagulha","desolação","evenshade overlook","feralas","lake dumont","front dos magram","mulgore","esconderijo dos proscritos","shendralas","vale dos ossos"},ang={["faction:Alliance"]="Uma região selvagem remota e disputada que oferece rotas alternativas entre Feralas e a região central de Kalimdor, repleta de perigos que exigem vigilância constante.",["faction:Horde"]="Posicionada logo além dos limites do sul de Mulgore, manter os Magram e os javatuscos contidos aqui é vital para proteger as fronteiras da Horda.",["race:NightElf"]="O nome evoca a antiga história dos Altaneiros de Eldre'Thalas, atraindo a atenção de sentinelas receosas com o uso imprudente da magia arcana no sul de Kalimdor.",["race:Tauren"]="Com a região fazendo fronteira com Mulgore e Desolação, a agressividade dos javatuscos e centauros ao longo dessas cordilheiras representa uma ameaça direta aos campos de caça ancestrais próximos."},sec={{t="Uma Fronteira em Turbulência",b="Escondida nas elevações a sudeste de Desolação e margeada por Mulgore e Feralas, Shen'dralas é uma fronteira rústica, muito distante das capitais das principais facções. Suas passagens escarpadas e enclaves ocultos abrigam grupos desesperados que lutam pela existência no limiar da selvagem Kalimdor. De pontos de observação isolados como Evenshade Overlook a refúgios sem lei como o Esconderijo dos Proscritos, a zona é definida por aqueles que desejam vigiar sem serem vistos ou permanecer esquecidos."},{t="Centauros, Javatuscos e Ruínas Antigas",b="A terra traz a marca distinta do legado altaneiro que lhe deu o nome, mas está longe de ser pacífica. O conflito dos centauros transborda pelo Front dos Magram, mantendo antigas rixas de sangue bem vivas ao longo de suas fronteiras. Enquanto isso, javatuscos invasores mantêm redutos fortificados, como o Refúgio dos Costagulha, transformando cada desfiladeiro sombrio em território disputado para qualquer viajante de passagem."},{t="O Vale dos Ossos",b="Partindo em direção a noroeste rumo a Desolação fica o Vale dos Ossos, um corredor sombrio que serve como a principal rota de acesso terrestre a Shen'dralas. Alvejada pelo sol e pelo vento, essa passagem permanece como uma dura lembrança das lutas violentas que ecoam constantemente por esses penhascos."}},faq={{q="Onde fica Shen'dralas?",a="Shen'dralas fica a sudeste de Desolação, aninhada entre as fronteiras de Feralas e Mulgore. Os viajantes que chegam a pé costumam entrar a partir de Desolação, passando pelo Vale dos Ossos.",al={"onde fica shendralas","localização de shendralas","como chegar a shendralas"}},{q="Shen'dralas é controlada pela Aliança ou pela Horda?",a="Nenhuma das facções detém domínio aqui. Shen'dralas é uma fronteira disputada, povoada por centauros errantes, javatuscos hostis, proscritos e acampamentos isolados.",al={"shendralas é da horda","shendralas é da aliança","quem controla shendralas"}},{q="Quais assentamentos ou marcos importantes existem aqui?",a="Entre os marcos proeminentes estão o Vale dos Ossos, o Refúgio dos Costagulha, Evenshade Overlook, o Front dos Magram, o Esconderijo dos Proscritos e a própria extensão central de Shen'dralas.",al={"subzonas de shendralas","marcos em shendralas","pontos de interesse em shendralas"}},{q="Por que há centauros aqui?",a="As guerras territoriais dos centauros estendem-se das planícies de Desolação diretamente para a região ao longo do Front dos Magram, onde o clã enfrenta defensores locais e facções rivais.",al={"centauros em shendralas","front dos magram","por que os magram estão aqui"}},{q="O que é o Refúgio dos Costagulha?",a="O Refúgio dos Costagulha é um entreposto fortificado mantido por javatuscos Costagulha, que estabeleceram uma base obstinada ao longo das bordas da zona.",al={"refúgio dos costagulha","javatuscos em shendralas"}},{q="Qual é a ligação entre esta zona e Lake Dumont?",a="Geograficamente, a vastidão selvagem de Shen'dralas abrange o território montanhoso onde o isolado Lake Dumont fica escondido em antigos mapas de reconhecimento.",al={"lake dumont","história do mapa de shendralas"}}},fp="11,286,23.441.0,36.393.0,19.282.0,29.189.0,55.155.0,45.172.0,27.175.0,28.139.0,57.153.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus é um deserto desolado e varrido pelo vento localizado no extremo sudoeste de Kalimdor. Abaixo de suas areias áridas jazem vastas colônias de silithids insetoides e as antigas ruínas de Ahn'Qiraj, seladas há um milênio atrás da formidável Muralha do Escaravelho. Hoje, os druidas do Círculo Cenariano mantêm uma vigília sob cerco contra enxames rastejantes e cultistas do apocalipse.",h="Silithus é um deserto desolado e varrido pelo vento localizado no extremo sudoeste de Kalimdor.",kw={"ahn'qiraj","forte cenariano","colme'ashi","colme'régia","colme'zora","palanque do escaravelho","muralha do escaravelho","silithid","silithus","twilight's hammer"},ang={["class:Druid"]="Como o coração das operações do Círculo Cenariano no sul de Kalimdor, Silithus convoca druidas para deter a corrupção da terra e confrontar as proles antinaturais que ameaçam o equilíbrio da natureza.",["profession:Herbalism"]="Apesar do terreno desértico rigoroso, maravilhas botânicas raras florescem aqui, incluindo Sálvia-prata-da-montanha, Folha-de-sonho, Ervassol e o excepcionalmente valioso Lótus Preto.",["profession:Mining"]="As rochas áridas e os túneis de insetos de Silithus abrigam alguns dos depósitos de Tório mais ricos do mundo, incluindo veios raros cobertos de lodo escondidos dentro das colmeias dos silithids.",["race:NightElf"]="Silithus é o campo de repouso sombrio onde seus ancestrais sangraram durante a Guerra das Areias Movediças, sacrificando milhares para selar os portões de Ahn'Qiraj."},sec={{t="A Fronteira do Deserto",b="Chegar a Silithus exige navegar pela selva primordial da Cratera Un'Goro e subir uma passagem larga e rochosa situada em seu canto noroeste. A transição é drástica: o crescimento primordial e luxuriante desaparece em uma vasta extensão de dunas movediças, pedra irregular e colmeias imponentes artificiais. Água é praticamente inexistente, e os ventos carregam o zumbido de asas de insetos e a areia sussurrante. O Círculo Cenariano mantém o Forte Cenariano próximo ao centro do deserto, servindo como o único baluarte de civilização e abrigo para viajantes, pesquisadores e guerreiros que enfrentam as terras devastadas hostis."},{t="Ecos das Areias Movediças",b="Há mil anos, esta extensão árida serviu como campo de batalha para a Guerra das Areias Movediças. Um exército aliado de elfos noturnos e grandes revoadas de dragões lutou desesperadamente para repelir os Qiraji, um império insetoide insidioso gerado da antiga civilização Aqiri. Quando a vitória total provou-se impossível, os defensores selaram os enxames dentro de sua fortaleza usando a Muralha do Escaravelho e o encantado Palanque do Escaravelho. Enquanto os portões monumentais resistiam, túneis subterrâneos permitiram que os silithids bestiais cavassem para fora, estabelecendo colônias extensas como Colme'Ashi, Colme'Zora e Colme'Régia por todas as areias."},{t="Uma Tempestade Convergente",b="O culto apocalíptico Twilight's Hammer se entrincheirou em vários postos avançados fortificados, invocando terrores elementais e venerando o poder sombrio que dorme sob Ahn'Qiraj. Observadores do Círculo Cenariano monitoram as colônias de silithids em expansão pelo deserto e a antiga ameaça atrás da Muralha do Escaravelho."}},faq={{q="Como chego a Silithus a pé?",a="Viaje para o canto noroeste da Cratera Un'Goro. Perto da curva sinuosa do rio, entre dois pilares de pedra natural proeminentes, uma estrada de terra inclinada leva para cima através da parede montanhosa da cratera diretamente para o deserto de Silithus.",al={"entrada de silithus","como chegar a silithus","caminho para silithus"}},{q="O que é a Muralha do Escaravelho?",a="A Muralha do Escaravelho é uma barreira maciça e encantada no sul de Silithus. Foi erguida há mil anos pelos elfos noturnos e pelas revoadas de dragões durante a Guerra das Areias Movediças para aprisionar o malévolo império Qiraji dentro de Ahn'Qiraj.",al={"portão de ahn'qiraj","muralha do escaravelho","o grande muro em silithus"}},{q="Quem administra o Forte Cenariano?",a="O Forte Cenariano é um posto avançado estabelecido e administrado pelo Círculo Cenariano. Seus druidas e guardiões aliados observam os enxames de silithids que avançam, investigam ruínas antigas e recebem viajantes neutros tanto da Aliança quanto da Horde.",al={"quem está no forte cenariano","facção do forte cenariano","forte cenariano amigável"}},{q="O que são os montes gigantes de insetos por toda a zona?",a="São as principais colmeias subterrâneas dos silithids: Colme'Ashi, Colme'Zora e Colme'Régia. Cada colmeia é uma extensa rede de túneis abrigando castas distintas de criaturas insetoides que servem às vontades trancadas atrás de Ahn'Qiraj.",al={"colmeias de silithus","colmeias de insetos em silithus","colme'ashi colme'zora"}},{q="O que o Twilight's Hammer está fazendo aqui?",a="O culto Twilight's Hammer mantém várias bases fortificadas em Silithus, incluindo o Acampamento do Crepúsculo e o Posto Crepúsculo. Eles conduzem rituais vis para invocar elementais e adoram as entidades antigas e malévolas sepultadas atrás da Muralha do Escaravelho.",al={"cultistas do crepúsculo em silithus","posto avançado do crepúsculo silithus","por que o twilight's hammer está em silithus"}}},fp="8,366,19.594.0,28.622.0,18.305.0,33.234.0,24.246.0,23.233.0,49.227.0,41.250.0"}
P.entries["zone:silverpine"] = {n="Floresta de Pinhaprata",s="A Floresta de Pinhaprata é uma mata sombria e envolta em névoa que se estende pela costa oeste de Lordaeron, entre as Clareiras de Tirisfal e a fechada Muralha Greymane. Assombrada pelas cicatrizes persistentes da praga do Flagelo, ela serve como a disputada fronteira sul dos Renegados. Os viajantes aqui enfrentam worgens ferozes vagando pelas sombras, gnolls enfermos e enclaves humanos hostis.",h="A Floresta de Pinhaprata é uma mata sombria e envolta em névoa que se estende pela costa oeste de Lordaeron...",kw={"lenhâmbar","arugal","ilha de fenris","muralha greymane","vilarejo lenhardente","rot hide","o sepulcro","bastilha da presa negra","floresta de pinhaprata"},ang={["class:Mage"]="A presença de Lenhâmbar e a queda do Arquimago Arugal na loucura lupina tornam Pinhaprata um conto sombrio de advertência sobre a magia do Kirin Tor que deu desastrosamente errado.",["faction:Alliance"]="Exploradores da Aliança encontrarão uma floresta profundamente hostil, interrompida apenas por uma frágil guarnição de Dalaran em Lenhâmbar e pelos trágicos aldeões amaldiçoados do Vilarejo Lenhardente.",["race:Undead"]="Pinhaprata representa a linha de frente imediata da expansão dos Renegados ao sul das Clareiras de Tirisfal, onde a Sociedade Real dos Boticários testa novas misturas e a Guarda Negra combate agentes remanescentes do Flagelo."},sec={{t="Uma Fronteira Assombrada",b="Outrora celebrada como uma exuberante maravilha de Lordaeron pela qual nobres viajantes seguiam rumo a Capital City, a Floresta de Pinhaprata definhou sob o impacto da Terceira Guerra. Névoas fantasmagóricas serpenteiam entre pinheiros agonizantes de casca prateada, e fazendas em ruínas jazem abandonadas à natureza selvagem. Ao norte ficam as Clareiras de Tirisfal, enquanto a margem leste faz fronteira com o Espelho de Lordaeron. Ao sul ergue-se a imponente e fechada Muralha Greymane, isolando o reino isolacionista de Guilnéas do caos ao redor. Os Renegados mantêm seu entreposto central n'O Sepulcro, lutando para proteger os bosques de inimigos por todos os lados."},{t="Os Worgens e a Presa Negra",b="O perigo mais infame de Pinhaprata é a maldição dos worgens. No alto da floresta a sudoeste fica a Bastilha da Presa Negra, antiga sede do Barão Silverlaine, hoje dominada pelo arquimago louco de Dalaran, Arugal. Buscando repelir o Flagelo durante a Terceira Guerra, Arugal evocou feras-lobos extradimensionais. As criaturas se voltaram contra seus invocadores, espalhando uma maldição licantrópica pelos bosques ao sul. No Vilarejo Lenhardente, aldeões de aparência humana comum cuidam de seus afazeres durante o dia, mas transformam-se em worgens selvagens sob o céu noturno."},{t="Enclaves Rivais e o Flagelo",b="O domínio dos Renegados sobre Pinhaprata é fortemente disputado tanto por facções vivas quanto mortas-vivas. A leste, na Ilha de Fenris, Thule Corvinalle lidera remanescentes do Flagelo enquanto comanda os gnolls Rot Hide assolados pela peste que infestam as fazendas do norte. No sul, magos humanos de Dalaran mantêm o assentamento fortificado de Lenhâmbar, conduzindo pesquisas místicas e opondo-se à expansão dos Renegados. A Sociedade Real dos Boticários e o Alto-executor Hadrec n'O Sepulcro travam uma campanha brutal e multifacetada para eliminar essas ameaças e testar novas e virulentas pragas."}},faq={{q="O que é a Muralha Greymane na fronteira sul?",a="A Muralha Greymane é uma colossal barreira de pedra erguida pelo Rei Genn Greymane para isolar completamente o seu reino de Guilnéas do restante de Lordaeron. Quando o Flagelo devastou o continente durante a Terceira Guerra, Guilnéas trancou seus portões e recusou ajuda externa, deixando as terras ao norte da muralha — incluindo o sul de Pinhaprata — entregues à própria sorte.",al={"por que tem uma muralha gigante","historia da muralha greymane","portao para guilneas"}},{q="Por que os habitantes do Vilarejo Lenhardente atacam à noite?",a="Os habitantes do Vilarejo Lenhardente sofrem com a maldição dos worgens do Arquimago Arugal. De dia, mantêm a forma humana e suas rotinas diárias, permanecendo amigáveis com a Aliança. Quando a lua nasce, a maldição ganha força, transformando toda a população em worgens selvagens e sanguinários que atacam com violência qualquer um por perto.",al={"misterio do vilarejo lenhardente","worgen de vilarejo lenhardente","por que humanos de lenhardente sao hostis a noite"}},{q="Quem é Thule Corvinalle?",a="Thule Corvinalle é um poderoso necromante a serviço do Flagelo. Operando a partir do Castelo Fenris na Ilha de Fenris, dentro do Espelho de Lordaeron, ele comanda legiões de mortos-vivos e exerce controle sobre os enfermos gnolls Rot Hide pelo leste de Pinhaprata, ameaçando diretamente o flanco oriental dos Renegados.",al={"quem lidera a ilha de fenris","historia de thule corvinalle","flagelo na ilha de fenris"}},{q="Por que Dalaran está ocupando Lenhâmbar?",a="Lenhâmbar é mantida por magos de Dalaran liderados pelo Arquimago Ataeric. Operando na vila, esses magos humanos monitoram os movimentos dos Renegados, estudam as aflições mágicas que assolam a floresta e buscam conter o surto próximo de worgens que se espalha a partir da Bastilha da Presa Negra.",al={"magos de lenhambar","por que a alianca esta em lenhambar","dalaran em pinhaprata"}},{q="O que é O Sepulcro?",a="O Sepulcro é o principal posto avançado militar e ponto de trânsito dos Renegados na Floresta de Pinhaprata. Sob o comando do Alto-executor Hadrec, serve como base de operações para patrulhas da Guarda Negra, batedores Rastreadores da Morte e para a Sociedade Real dos Boticários na luta para proteger a floresta.",al={"cidade da horda em pinhaprata","onde fica o ponto de voo","historia do sepulcro"}},{q="Jogadores da Aliança podem fazer missões na Floresta de Pinhaprata?",a="A Floresta de Pinhaprata não possui centros de missões ou cidades amigáveis para a Aliança; todas as missões locais pertencem com exclusividade à Horda. Aventureiros da Aliança geralmente só entram na floresta ao viajar de Costa Sul para explorar a Bastilha da Presa Negra ou combater forças hostis dos Renegados.",al={"pinhaprata e so para horda","missoes da alianca em pinhaprata","alianca pode ir para pinhaprata"}}},fp="17,362,18.611.0,25.536.0,30.560.1,49.350.0,57.329.0,23.292.0,35.268.0,22.284.0,48.260.0"}
P.entries["zone:stockade"] = {n="O Cárcere",s="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da cidade, perto do Distrito dos Magos. Construído para deter os criminosos mais perigosos, insurgentes políticos e inimigos do estado capturados do reino, as instalações colapsaram recentemente em uma anarquia violenta. O Carcereiro-chefe Thelágua foi forçado a recuar para a entrada, recrutando desesperadamente aventureiros capazes para esmagar a rebelião por dentro antes que ela se espalhe para a capital.",h="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da...",kw={"basílio taborda","bruegal ferroque","canais","defias","flávio lúcio","ramoque","kam fundafúria","rebelião","o cárcere","ventobravo","targorr","carcereiro-chefe thelágua"},ang={["class:Mage"]="Localizada bem na beira do canal do Distrito dos Magos, a prisão contém brigões físicos vulneráveis a magias de lentidão, enquanto o ogro mago Ramoque pode liberar uma Cadeia de Raios.",["class:Rogue"]="O layout da prisão apresenta uma rede complexa de celas de ferro trancadas e conexões com a Irmandade Défias, oferecendo prática única de arrombamento de fechaduras e informações sobre o sindicato do submundo de Basílio Taborda.",["faction:Alliance"]="A rebelião ameaça o próprio coração da capital; conter a revolta preserva a segurança interna de Ventobravo enquanto honra recompensas não oficiais para Montanhas Cristarrubra, Floresta do Crepúsculo e Altaforja.",["race:Dwarf"]="A presença de Kam Fundafúria nas celas de Ventobravo é uma afronta a Dun Modr; o Reino de Altaforja exige a cabeça dele para vingar as vidas anãs perdidas nas Pantanal."},sec={{t="Uma Prisão sob Cerco",b="Sob os canais tranquilos de Ventobravo, O Cárcere tornou-se uma zona de guerra. Quando o exército regular marchou para lutar em frentes distantes, a prisão, com falta de pessoal, passou a depender de jovens inexperientes — incluindo recrutas de catorze anos — para manter a ordem. Não funcionou. Os detentos iniciaram uma rebelião sangrenta e coordenada, rasgando seus cobertores de lã para fazer bandanas de gangue e eliminando os guardas restantes. O Carcereiro-chefe Thelágua mal conseguiu manter o controle da entrada, deixando as celas, corredores e blocos de detenção nas mãos impiedosas dos condenados."},{t="Nobres e Assassinos",b="A rebelião expôs o lado feio da máquina política de Ventobravo. Territórios externos há muito estavam frustrados com a Casa dos Nobres suspendendo execuções para sua própria vantagem. O Guarda Berto, de Vila Plácida, queria que o orc capturado Targorr, o Horror fosse executado por suas atrocidades, apenas para ver os nobres congelarem a sentença. O Conselheiro Bonfá-lobos, de Vila Sombria, viu o ladrão de túmulos Flávio Lúcio ser poupado da forca, apesar de profanar túmulos para o necromante Morbent Fel. Até os anões de Dun Modr enviaram mensagens exigindo a morte do sabotador Dark Iron Kam Fundafúria. Com O Cárcere em caos, as autoridades locais contrataram silenciosamente aventureiros para realizar as execuções que os tribunais da capital se recusaram a aplicar."},{t="O Mentor e os Rebeldes",b="Por trás do colapso sincronizado da prisão está Basílio Taborda, um criminoso astuto ligado diretamente à Irmandade Défias, que orquestrou a revolta de sua cela. Entre os rebeldes está Bruegal Ferroque, um perigoso brigão anão. Ele é um dos vários condenados endurecidos que os aventureiros podem encontrar enquanto ajudam Thelágua a retomar a prisão."}},faq={{q="Por que O Cárcere está em rebelião aberta?",a="A Irmandade Défias orquestrou uma rebelião em toda a prisão enquanto as instalações estavam com falta de pessoal. Com o Exército de Ventobravo destacado para frentes de batalha distantes, voluntários adolescentes foram deixados guardando assassinos endurecidos. Os condenados emboscaram a equipe, apreenderam armas e forçaram o Carcereiro-chefe Thelágua a sair dos blocos de celas.",al={"por que a rebelião","o que aconteceu no cárcere","causa da rebelião no cárcere"}},{q="Quem está comandando a revolta lá dentro?",a="O mentor por trás da revolta é Basílio Taborda, um influente criminoso da Irmandade Défias encarcerado no bloco de celas leste. Outros prisioneiros perigosos incluem Bruegal Ferroque, Ramoque e Kam Fundafúria.",al={"chefe do cárcere","quem lidera a rebelião","quem comanda o cárcere"}},{q="Por que prisioneiros como Targorr e Flávio Lúcio ainda estão vivos?",a="Ambos foram condenados à morte, mas políticos corruptos dentro da Casa dos Nobres impuseram impedimentos burocráticos às suas execuções para usá-los como alavancagem política. Essa interferência indignou aliados em Vila Plácida e Vila Sombria, levando-os a enviar aventureiros para eliminar os prisioneiros durante o caos.",al={"por que targorr não foi executado","julgamento de flávio lúcio","corrupção da casa dos nobres"}},{q="O que derrotar Bruegal Ferroque significa para a prisão?",a="Bruegal Ferroque é um perigoso brigão anão entre os rebeldes. Derrotá-lo remove uma ameaça da prisão enquanto os aventureiros trabalham para conter a rebelião.",al={"história de bruegal ferroque","matar bruegal","quem é bruegal"}},{q="Por que há anões Dark Iron e orcs dentro de uma cadeia humana?",a="O Cárcere serve como uma prisão de segurança máxima para prisioneiros de guerra de alto valor. Targorr, o Horror liderou ataques de orcs Blackrock em Montanhas Cristarrubra, enquanto Kam Fundafúria realizou sabotagem para o clã Dark Iron nas Pantanal antes de ambos serem capturados e transferidos para a capital.",al={"por que anões dark iron estão aqui","história de kam fundafúria","targorr no cárcere"}},{q="Jogadores da Horda podem entrar em O Cárcere?",a="Sim, mas é excepcionalmente perigoso. A entrada da masmorra fica diretamente dentro de Ventobravo, perto dos canais do Distrito dos Magos. Infiltrados da Horda devem passar furtivamente pelos guardas da cidade e pelos defensores da capital para alcançar o portal.",al={"a horda pode fazer o cárcere","horda na prisão de ventobravo"}}},fp="12,455,20.556.0,20.705.1,30.341.1,38.314.0,35.198.0,60.303.0,60.167.0,61.278.0,37.226.0"}
P.entries["zone:stonetalon"] = {n="Cordilheira das Torres de Pedra",s="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira com o Vale Gris, os Sertões e Desolação. Venerada tanto pelos elfos noturnos quanto pelos taurens como um santuário sagrado, as alturas consagradas da região contrastam fortemente com a fumaça e o maquinário que sufocam seus cânions inferiores. Hoje, as montanhas estão assoladas pelo desmatamento, pela devastação elemental instável e por crescentes hostilidades de fronteira.",h="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira...",kw={"vale carbonizado","hanfritz schaventorck","malaka'jin","cordilheira das torres de pedra","morro das torres de pedra","retiro rocha do sol","talondeep pass","rochedo cortavento"},ang={["class:Druid"]="A profanação do Rochedo Cortavento e a corrupção calcinada do Vale Carbonizado servem como um grave chamado para druidas que buscam acalmar espíritos da natureza enfurecidos e proteger ninhos sagrados.",["class:Shaman"]="O clamor dos espíritos da montanha sob o ataque das perfuratrizes dos goblins pode ser ouvido até em Orgrimmar, chamando xamãs para conter elementais da terra enfurecidos e restaurar o equilíbrio dos picos.",["faction:Alliance"]="Estacionada no alto do Morro das Torres de Pedra e em acampamentos ocultos ao redor do Rochedo Cortavento, a Aliança defende covis ancestrais kaldorei de máquinas goblins e de rivais territoriais invasores.",["faction:Horde"]="Os aventureiros da Horda contam com o refúgio isolado do Retiro Rocha do Sol e o posto troll meridional de Malaka'jin para frear a poluição industrial dos Empreendimentos S.A. e erradicar os perigosos foras da lei do Totem Sombrio."},sec={{t="Os Maus Ventos e os Picos",b="Erguendo-se abruptamente da região central de Kalimdor, a cordilheira das Torres de Pedra retém a umidade trazida dos mares ocidentais, originando tempestades repentinas e trilhas traiçoeiras de arenito escorregadio pela chuva. A característica mais marcante dos vales inferiores é o vento cortante e incessante conhecido como os Maus Ventos, capaz de cegar viajantes com poeira ou atirar os desatentos diretamente de penhascos íngremes. Mais acima, florestas de coníferas cobrem as encostas ao redor do Morro das Torres de Pedra, onde os elfos noturnos cuidam de covis ancestrais e clareiras, vigiando os ninhos sagrados de mantícoras e hipogrifos que habitam o Lago Mirkfallon."},{t="Indústria e Intrusão",b="A solidão pacífica da cordilheira foi violentamente interrompida pela chegada dos Empreendimentos S.A. Montando extensos acampamentos de extração de madeira e escavando profundas minas a céu aberto no Rochedo Cortavento, os goblins — auxiliados pelo demente gnomo leproso Hanfritz Schaventorck — desmataram árvores centenárias, escureceram os céus com fumaça de fornalhas e despejaram detritos industriais nas águas da montanha. A ganância deles provocou uma retaliação rápida: xamãs locais de Orgrimmar responderam aos gritos agoniados dos espíritos da montanha, enquanto pequenos acampamentos da Aliança nas proximidades lutam contra os profanadores para proteger o que resta das terras altas."},{t="Cicatrizes do Passado",b="Ao sul fica o Vale Carbonizado, outrora uma natureza exuberante, agora reduzido a uma terra devastada coberta de cinzas e tomada por elementais do fogo rebeldes, dracônicos negros e harpias. Embora os picos tenham sido o local histórico onde a Horda e a Aliança forjaram uma frágil trégua durante a Terceira Guerra sob a orientação do misterioso Oráculo, as relações atuais estão se deteriorando. Taurens renegados do Totem Sombrio operam a partir de acampamentos capturados, e trolls Lançanegra em Malaka'jin entram em conflito com incursões da Aliança vindas dos Sertões e do Vale Gris."}},faq={{q="Como chego à Cordilheira das Torres de Pedra?",a="A maioria dos viajantes entra pelo Desfiladeiro da Garra Profunda, uma trilha na montanha que corta a cordilheira a partir do sudoeste do Vale Gris. Também há trilhas elevadas que levam ao sul para Desolação e caminhos que descem a leste diretamente para as extensões setentrionais dos Sertões.",al={"entrada da cordilheira das torres de pedra","como chegar à cordilheira das torres de pedra","estrada da cordilheira das torres de pedra"}},{q="Por que o Vale Carbonizado está queimado e arruinado?",a="O Vale Carbonizado já foi um refúgio luxuriante, mas uma devastação cataclísmica consumiu o vale em chamas. Ele foi reduzido a uma ruína fumegante infestada de agressivos elementais do fogo, draconetes rebeldes e harpias mortais.",al={"fogo no vale carbonizado","o que aconteceu com o vale carbonizado","por que o vale carbonizado queimou"}},{q="O que os Empreendimentos S.A. estão fazendo no Rochedo Cortavento?",a="Os Empreendimentos S.A. estão desmatando árvores impiedosamente e perfurando fundo a encosta da montanha em busca de riquezas minerais. Suas operações poluíram o Lago do Rochedo com graxa de motor, devastaram os vales e enfureceram os espíritos locais e os habitantes nativos.",al={"empreendimentos s.a. cordilheira das torres de pedra","goblins do rochedo cortavento","por que goblins cortam arvores"}},{q="Onde ficam os principais mestres de voo?",a="Os heróis da Aliança usam o mestre de voo situado no santuário elevado do Morro das Torres de Pedra, ao norte, enquanto os aventureiros da Horda se estabelecem na aldeia montanhosa central do Retiro Rocha do Sol.",al={"rota de voo da cordilheira das torres de pedra","onde fica o ponto de voo da cordilheira das torres de pedra","ponto de voo cordilheira das torres de pedra"}},{q="O que aconteceu no Morro das Torres de Pedra durante a Terceira Guerra?",a="Guiados por visões do Profeta Medivh, Thrall e Jaina Proudmore subiram as cavernas do Morro das Torres de Pedra em busca do Oráculo. Lá, os líderes das duas facções forjaram a histórica aliança temporária que se uniu contra a Legião Ardente no Monte Hyjal.",al={"historia do morro das torres de pedra","o oraculo da cordilheira das torres de pedra","terceira guerra cordilheira das torres de pedra"}},{q="Quem são os Totem Sombrio na Cordilheira das Torres de Pedra?",a="Os Totem Sombrio são uma tribo tauren implacável e renegada, hostil a influências externas. Na Cordilheira das Torres de Pedra, eles ocuparam um posto montanhoso perto da fronteira com os Sertões, aterrorizando viajantes locais e fazendo prisioneiros.",al={"aldeia do temível totem","totem sombrio cordilheira das torres de pedra"}}},fp="20,410,27.610.0,22.630.0,17.537.0,41.251.0,42.215.0,52.258.0,42.193.0,54.257.0,36.219.0"}
P.entries["zone:stormwind"] = {n="Ventobravo",s="Ventobravo é a movimentada capital do Reino de Ventobravo e o principal bastião humano no mundo após a queda de Lordaeron. Reerguida das cinzas pela Guilda dos Pedreiros após sua destruição na Primeira Guerra, seus magníficos distritos de pedra branca agora abrigam o coração da Grande Aliança. Sob seus majestosos canais e catedrais, no entanto, a cidade lida com o repentino desaparecimento do Rei Varian Wrynn e uma crescente intriga política.",h="Ventobravo é a movimentada capital do Reino de Ventobravo e o principal bastião humano no mundo após a queda...",kw={"anduin","bolvar","catedral","correfundo","prestor","pedreiros","ventobravo","vancleef","wrynn"},ang={["class:Paladin"]="A Catedral da Luz serve como o supremo santuário de sua fé no sul, treinando cavaleiros do Punho de Prata e defendendo a justiça.",["class:Rogue"]="Sob as ruas imaculadas de pedra fica o quartel-general da AVIN na Cidade Velha, comandando a principal rede de inteligência e espionagem da Aliança.",["faction:Alliance"]="Como a metrópole mais populosa da Grande Aliança, Ventobravo fornece poderio naval, base espiritual e uma liderança diplomática vital.",["race:Dwarf"]="Por meio do Metrô Correfundo, seus parentes no Distrito dos Anões mantêm laços comerciais profundos e forjam conexões militares fraternas com o reino humano.",["race:Human"]="Ventobravo se ergue como a última grande sede de soberania do seu povo após a destruição de Lordaeron, Alterac e Dalaran no norte."},sec={{t="Renascida das Cinzas",b="Fundada há mais de um milênio pelos descendentes dos Arathi, Ventobravo permaneceu por gerações como um reino próspero e autossuficiente. Essa era de ouro terminou quando a Horda Órquica atravessou o Portal Negro, assolando o continente meridional e arrasando a capital na Primeira Guerra. Sobreviventes liderados por Sir Anduin Lothar fugiram para o norte através do Grande Oceano em direção a Lordaeron. Após a derrota da Horda na Segunda Guerra, o Rei Terenas Menethil II e a Aliança financiaram uma reconstrução completa. A Guilda dos Pedreiros reconstruiu meticulosamente a capital, transformando-a na Nova Ventobravo — uma cidadela reluzente de pedra branca polida e bairros entrelaçados por canais."},{t="Uma Corte Dividida",b="Apesar de sua majestade exterior, a capital está presa em um tumulto interno. Uma disputa entre a Casa dos Nobres e a Guilda dos Pedreiros por salários deixou o reino paralisado por dívidas. A revolta subsequente tirou a vida da Rainha Tiffin Wrynn e empurrou os artesãos exilados para a criminalidade, dando origem à Irmandade Défias. Agora, o Rei Varian Wrynn desapareceu misteriosamente a caminho de uma cúpula diplomática. Para evitar o pânico, a coroa foi colocada sobre seu jovem filho, o Príncipe Anduin Wrynn, de dez anos, com o Grão-lorde Bolvar Fordragon governando como Regente e comandante militar ao lado da conselheira real Lady Katrana Prestor."},{t="Coração da Grande Aliança",b="Com Lordaeron tomada pelo Flagelo, Ventobravo herdou o manto de maior refúgio da humanidade e epicentro da Aliança. Ela se conecta diretamente ao reino anão de Altaforja através do subterrâneo Metrô Correfundo do Grão-mecânico Mekkatorque. Os visitantes que cruzam o Vale dos Heróis são recebidos por imponentes estátuas dos Filhos de Lothar, que desapareceram além do Portal Negro. Do farol espiritual da Catedral da Luz aos estudos arcanos no Sacrário dos Teurgos, Ventobravo se ergue como o supremo polo de comércio, cultura e defesa pelos mares do sul."},{t="Sombras na Fortaleza",b="A discórdia que aflige o reino não é mero acidente administrativo. Lady Katrana Prestor tem guiado secretamente as decisões da Casa dos Nobres, inflamando a hostilidade contra os pedreiros e negligenciando deliberadamente os apelos por socorro militar vindos de povoados distantes como Cerro Oeste e as Montanhas Cristarrubra. Sussurrando veneno aos ouvidos do Grão-lorde Bolvar e dividindo a atenção do reino, ela busca manter as legiões de Ventobravo ociosas e desunidas enquanto a agitação que se espalha além dos muros da cidade ameaça o próprio trono."}},faq={{q="Quem governa Ventobravo neste momento?",a="O Príncipe Anduin Wrynn, de dez anos, detém a coroa, mas o governo de fato é exercido pelo Grão-lorde Bolvar Fordragon, que atua como Regente de Ventobravo e comandante supremo de suas forças armadas. Bolvar depende fortemente dos conselhos da conselheira real Lady Katrana Prestor enquanto o Rei Varian Wrynn permanece desaparecido.",al={"rei atual","quem é o rei","quem lidera ventobravo","rei de ventobravo"}},{q="O que aconteceu com o Rei Varian Wrynn?",a="O Rei Varian desapareceu sob circunstâncias suspeitas enquanto viajava de navio para uma cúpula diplomática em Theramore. Seu sumiço foi mantido em sigilo para preservar a estabilidade, embora boatos circulem desenfreados pelas ruas e pelos campos.",al={"onde está varian","rei desaparecido","sumiço de varian","varian wrynn desaparecido"}},{q="Por que a cidade foi reconstruída e por quem?",a="A cidade original foi reduzida a cinzas pela Horda Órquica durante a Primeira Guerra. Após a Segunda Guerra, a Guilda dos Pedreiros, liderada pelo mestre artífice Edwin VanCleef, reconstruiu meticulosamente a capital em pedra branca reluzente, com apoio financeiro da Aliança de Lordaeron.",al={"quem reconstruiu ventobravo","guilda dos pedreiros","nova ventobravo","reconstrução da cidade"}},{q="Por que os pedreiros se rebelaram contra a coroa?",a="A Casa dos Nobres acumulou dívidas vultosas expandindo as forças armadas de Ventobravo e recusou-se a pagar à Guilda dos Pedreiros os salários prometidos. Quando Edwin VanCleef exigiu a compensação, os nobres dissolveram a guilda. Os trabalhadores se revoltaram, a Rainha Tiffin Wrynn foi morta por uma pedra atirada, e os pedreiros exilados formaram a Irmandade Défias.",al={"origem dos défias","por que os défias revoltaram","revolta dos pedreiros","morte da rainha tiffin"}},{q="Quem são as estátuas gigantes no Vale dos Heróis?",a="As estátuas homenageiam os Filhos de Lothar: General Turalyon, Capitã-patrulheira Alleria Correventos, Arquimago Hadggar, Kurdran Martelo Feroz e Danath Trollbano. Elas foram erguidas para celebrar os heróis que se aventuraram através do Portal Negro até Draenor para selar a fenda e proteger Azeroth.",al={"estátuas da entrada","estátuas do vale dos heróis","estátuas dos filhos de lothar"}},{q="Como Ventobravo se conecta a Altaforja?",a="Ventobravo é ligada a Altaforja pelo Metrô Correfundo, uma ferrovia subterrânea construída pelo Grão-mecânico Gelbin Mekkatorque e encomendada pelo Rei Magni Barbabronze para permitir comércio ágil e reforço militar rápido entre ambas as capitais.",al={"metrô correfundo","trem para altaforja","como ir para altaforja"}},{q="Por que Ventobravo não está enviando tropas para ajudar Cerro Oeste e as Montanhas Cristarrubra?",a="A corte real, sob forte conselho de Lady Katrana Prestor, insiste que a cidade não pode dispensar tropas de suas próprias muralhas e fronteiras imediatas. Com as finanças do reino combalidas e as disputas políticas paralisando a Casa dos Nobres, as cidades regionais foram abandonadas à própria sorte, dependendo de milícias locais.",al={"exército de ventobravo sumido","por que sem ajuda em cerro oeste","reforços recusados"}}},fp="14,461,19.657.0,15.605.0,27.577.0,19.516.2,30.299.0,35.231.0,38.286.0,48.333.0,50.279.0,40.240.0,65.292.0"}
P.entries["zone:stranglethorn"] = {n="Selva do Espinhaço",s="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da Floresta do Crepúsculo. Outrora a sede do grande Império Gurubashi, a floresta tropical agora está repleta de ruínas de trolls em ruínas, feras selvagens e acampamentos rivais de goblins, piratas e soldados. O controle da região é disputado ferozmente por tribos de trolls locais, pela Empreendimentos S.A. e por facções rivais que tentam estabelecer pontos de apoio no calor da selva.",h="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da...",kw={"vela sangrenta","angra do butim","grom'gol","gurubashi","kurzen","nesingwary","rezingada","selva do espinhaço","empreendimentos s.a.","zul'gurub"},ang={["class:Hunter"]="A margem norte do rio abriga o famoso caçador de caça grossa Rosarães Guima, que desafia atiradores a testar sua coragem rastreando os mais ferozes raptores, panteras e crocoliscos da selva.",["faction:Alliance"]="Os esforços históricos de Ventobravo para conquistar e pacificar a selva sobrecarregaram o reino com pesadas dívidas e, hoje, seus interesses são defendidos apenas por amotinados em apuros no Acampamento dos Rebeldes.",["faction:Horde"]="O Acampamento Grom'gol oferece à Horda uma fortaleza estratégica indispensável no continente meridional, abastecida diretamente por zepelins de Durotar e da Cidade Baixa.",["profession:Herbalism"]="A copa úmida da floresta nutre uma flora valiosa, tornando as margens dos rios e as costas locais ideais para colher Ácera-agreste, Folha-da-névoa, Espinheira-dourada e Lótus Roxo.",["race:Troll"]="O Espinhaço é o berço ancestral dos trolls da selva, cujo antigo império Gurubashi sucumbiu à guerra civil após adorar Hakkar, o Esfolador de Almas, empurrando tribos como a Lançanegra para além dos mares."},sec={{t="Ruínas de um Império",b="Por milênios, a selva foi governada pelo poderoso Império Gurubashi a partir de sua capital, Zul'Gurub. Esse domínio se desfez quando sacerdotes radicais evocaram Hakkar, o Esfolador de Almas, mergulhando a região em uma guerra civil catastrófica. Embora os Zandalari tenham intervindo para esmagar a revolta do deus de sangue, o império se fragmentou de forma irreparável. Hoje, a selva está infestada por facções sucessoras em guerra — principalmente os Bloodscalp no noroeste e os Rachacrânio no leste —, ambas massacrando forasteiros com fervor para recuperar seu lar ancestral."},{t="Piratas e Exploradores",b="Onde as ruínas antigas jazem em silêncio, a ganância comercial preenche o vazio. No extremo sul fica a Angra do Butim, um refúgio movimentado construído pelo Cartel Bondebico e administrado pelos Blackwater Raiders sob o comando do Barão Rezingada. O porto serve como o principal centro do comércio do sul e do transporte marítimo, embora seja perpetuamente sitiado pelos rivais Bucaneiros da Vela Sangrenta, ancorados ao longo da costa. Mais para o interior, a Empreendimentos S.A. desmata a selva agressivamente em busca de madeira e minera as colinas atrás de raros cristais cantantes."},{t="Uma Terra Selvagem Disputada",b="A Selva do Espinhaço serve como uma das fronteiras mais voláteis do mundo. A Horda comanda o Acampamento Grom'gol na costa oeste, ligado por zepelins goblins a Durotar e às Clareiras de Tirisfal, enquanto legalistas da Aliança operam a partir do Acampamento dos Rebeldes para caçar o Coronel Kurzen, que desertou. Entre a folhagem densa, o lendário caçador Rosarães Guima lidera audaciosas expedições de caça grossa, atraindo viajantes a encontros perigosos com panteras à espreita, macacos enormes e soldados inimigos."},{t="A Loucura na Selva",b="Nem todas as ameaças no norte do Espinhaço são feras selvagens. O Coronel Kurzen, outrora um comandante condecorado enviado por Ventobravo, enlouqueceu na mata e estabeleceu um reduto mercenário tirânico. Na verdade, a mente de Kurzen foi enredada pela feitiçaria do Olho da Mente, um artefato empunhado pelo ogro mago Mai'Zoth, da vizinha Gruta de Mosh'Ogg, mergulhando a expedição em pura insanidade e levando seus antigos homens a formar o dissidente Acampamento dos Rebeldes."}},faq={{q="Quem controla a Selva do Espinhaço?",a="Nenhum poder único governa a selva. A região é dividida entre tribos rivais de trolls da selva, como os Bloodscalp e os Rachacrânio, acampamentos renegados como o Complexo do Kurzen, os mercenários da Empreendimentos S.A. e postos militares dispersos da Horda e da Aliança. O maior assentamento urbano é o porto goblin neutro da Angra do Butim, governado pelo Barão Rezingada e pelos Blackwater Raiders.",al={"quem controla a selva do espinhaço","quem governa a selva do espinhaço","facções da selva do espinhaço"}},{q="O que é a Angra do Butim?",a="A Angra do Butim é uma ampla cidade portuária construída nos penhascos ao sul do Cabo do Espinhaço. Originalmente um assentamento humano conhecido como Angra Aguanegra, foi capturada por trolls e, com o tempo, garantida pelo Cartel Bondebico. Hoje, o Barão Rezingada e o Mestre de Frota Chifre do Mar a administram como um porto comercial neutro que conecta viajantes à Vila Catraca através do Grande Oceano.",al={"o que é angra do butim","porto de angra do butim","quem comanda angra do butim"}},{q="Por que o Coronel Kurzen desertou?",a="O Coronel Kurzen liderou uma expedição à selva em nome de Ventobravo, mas sua mente sucumbiu à influência de Mai'Zoth, um ogro mago que empunhava uma poderosa relíquia chamada Olho da Mente. Kurzen tornou-se cada vez mais errático e despótico, forçando soldados leais, como o Tenente Doren, a romper laços e formar o Acampamento dos Rebeldes para detê-lo.",al={"por que kurzen é mau","o que aconteceu com kurzen","história de kurzen"}},{q="O que é Zul'Gurub?",a="Zul'Gurub é a antiga capital do Império Gurubashi, repleta de templos e encravada no nordeste do Espinhaço. Foi o epicentro da guerra civil que destruiu o império quinze séculos atrás, após sacerdotes radicais evocarem o deus de sangue Hakkar, o Esfolador de Almas. Embora abandonada há muito tempo às trepadeiras e ruínas, rituais sombrios continuam a ameaçar seus salões.",al={"o que é zg","história de zul'gurub","capital dos gurubashi"}},{q="O que era a Pedra das Marés?",a="A Pedra das Marés é uma relíquia lendária da história antiga dos Gurubashi, descoberta na costa por um guerreiro troll. Ela concedia ao seu portador domínio sobre a água e invocações elementais semelhantes às de um poderoso mago, rendendo ao usuário o título de 'Portador das Marés'. No entanto, carregava uma maldição que fazia o portador desaparecer lentamente do reino físico, levando cada usuário a caminhar em direção ao mar e sumir para sempre.",al={"pedra das marés","lenda do portador das marés","pedra da água gurubashi"}},{q="Como viajo até a Selva do Espinhaço?",a="Os viajantes podem caminhar para o sul atravessando a fronteira do rio a partir da Floresta do Crepúsculo até o norte do Espinhaço. A Horda mantém torres diretas de zepelim conectando o Acampamento Grom'gol a Durotar e às Clareiras de Tirisfal. Viajantes de Kalimdor também podem embarcar na embarcação mercante regular que navega entre a Vila Catraca, nos Sertões, e a Angra do Butim.",al={"como chegar à selva do espinhaço","chegar à selva do espinhaço","viagem selva do espinhaço"}}},fp="18,435,18.552.0,22.509.0,22.494.0,25.463.1,32.373.0,18.360.0,32.325.1,18.354.0,32.393.0,38.317.0"}
P.entries["zone:swampofsorrows"] = {n="Pântano das Mágoas",s="O Pântano das Mágoas é uma área úmida, turva e salobra situada entre a Trilha do Vento Morto e a árida Barreira do Inferno. Outrora a extensão setentrional do antigo Black Morass, seus pântanos com crostas de sal abrigam uma fauna perigosa, draconianos verdes e o Templo de Atal'Hakkar em ruínas, submerso sob o Poço de Lágrimas. Enquanto a Horda mantém a guarnição fortificada de Pedregal, a Aliança não possui nenhum refúgio seguro no lodaçal, deixando a natureza praticamente indomada.",h="O Pântano das Mágoas é uma área úmida, turva e salobra situada entre a Trilha do Vento Morto e a árida...",kw={"black morass","broken","o refúgio","os perdidos","poço de lágrimas","penumbra das mágoas","pedregal","templo submerso","pântano das mágoas","templo de atal'hakkar"},ang={["faction:Alliance"]="Sem um entreposto para se recompor, viajar pelo pântano é um empreendimento isolado e hostil que exige preparação cuidadosa a partir de Vila Sombria ou da Bastilha de Etergarde.",["faction:Horde"]="Pedregal serve como seu reduto avançado vital no continente meridional, oferecendo rotas diretas de mantícora para Karrath, Monte Candente e Acampamento Grom'gol.",["profession:Blacksmithing"]="Aventureiros resistentes podem minerar ferro, ouro, mitril e veraprata ao longo dos penhascos montanhosos que emolduram as bordas norte e sul do pântano.",["profession:Herbalism"]="O brejo é um dos poucos lugares em Azeroth ricos em erva-cega, além de possuir vegetações fartas de raiz-da-vida, folha-do-ocaso e estranguladora.",["race:Troll"]="As ruínas submersas de Atal'Hakkar servem como uma lembrança sombria da magia de sangue nefasta que fragmentou o Império Gurubashi e atraiu a ira dos Aspectos Dragônicos."},sec={{t="Uma História Submersa",b="Muito antes da chegada da Horda Órquica, estes pântanos formavam a metade norte de uma enorme área úmida conhecida como Black Morass. Após a fragmentação do Império Gurubashi, os fanáticos trolls Atal'ai fugiram para o brejo para erguer o Templo de Atal'Hakkar, com a intenção de evocar seu loa sanguinário, Hakkar, o Esfolador de Almas. Sentindo a catástrofe iminente, o Aspecto Ysera libertou seus poderes, afundando a pirâmide amaldiçoada sob as águas do Poço de Lágrimas. Guardiões da revoada dragônica verde liderados por Eranikus foram posicionados para vigiar vigilantemente a estrutura afogada. Quando o cataclismo do Portal Negro mais tarde calcinou a parte sul do pântano, transformando-a na Barreira do Inferno, este brejo setentrional recebeu seu atual e doloroso nome."},{t="Postos Avançados e Exilados Degenerados",b="Pedregal serve como o principal ponto de apoio civilizado no pântano. Estabelecido originalmente durante a Primeira Guerra ao lado dos agora arruinados assentamentos de Rockard e Kyross, o entreposto foi reconstruído sob o comando de Thrall para servir como o ponto de concentração mais meridional da Horda nos Reinos do Leste. Além das paliçadas de Pedregal, viajantes estranhos vagueiam pelo brejo. Um grupo de draeneis desgarrados, encalhados em Azeroth, sucumbiu à saudade de casa e à loucura, degenerando nos selvagens Os Perdidos. No entanto, um pequeno enclave de exilados Broken lúcidos resiste no O Refúgio, cautelosos, mas dispostos a negociar pacificamente com viajantes."},{t="O Brejo Submerso",b="Sobreviver ao pântano exige vigilância constante contra sua fauna predatória. Podaçais profundos ocultam crocoliscos à espreita, aranhas venenosas, onças-do-pântano rondantes e bestas-do-pântano errantes incrustadas de detritos do brejo. Cavernas costeiras e a Praia Brumalga fervilham de murlocs cruéis, enquanto a maré carregada de sal avança continuamente terra adentro, preservando troncos podres em grossas crostas salobras. Mais a leste fica a Penumbra das Mágoas, onde draconianos de elite agressivos protegem ferozmente os acessos ao Templo Submerso, atacando qualquer um que se aproxime de sua vigília."}},faq={{q="Como chego ao Pântano das Mágoas?",a="A rota terrestre mais comum segue para o leste a partir de Vila Sombria, na Floresta do Crepúsculo, atravessa o perigoso e assombrado desfiladeiro da Trilha do Vento Morto e desce direto para o pântano. Como alternativa, viajantes vindos do sul podem caminhar para o norte pela estrada principal que sai da Barreira do Inferno.",al={"como chegar ao pântano das mágoas","estrada do pântano das mágoas","como chegar a pedregal"}},{q="Por que o Templo de Atal'Hakkar está debaixo d'água?",a="Séculos atrás, o sacerdócio Atal'ai tentou evocar Hakkar, o Esfolador de Almas, em Azeroth. Ysera, o Aspecto Dragônico da Revoada Verde, descobriu seus ritos de sangue demoníacos e afundou todo o templo no brejo para evitar o desastre, deixando para trás draconianos verdes para vigiar os salões submersos.",al={"por que o templo submerso afundou","quem afundou o templo","história do templo submerso"}},{q="O que é Pedregal?",a="Pedregal foi um dos primeiros assentamentos construídos pela Horda Órquica após cruzar o Portal Negro durante a Primeira Guerra. Embora tenha sido devastado durante os combates, foi recentemente recuperado e reconstruído sob as ordens de Thrall para consolidar a logística da Horda perto da Barreira do Inferno.",al={"história de pedregal","base órquica no pântano","quem construiu pedregal"}},{q="Existe algum assentamento da Aliança aqui?",a="Não. A Aliança não mantém cidades, guardas ou rotas de voo no Pântano das Mágoas. Aventureiros da Aliança operando na área precisam usar como base Vila Sombria, na Floresta do Crepúsculo a oeste, ou a Bastilha de Etergarde, na Barreira do Inferno ao sul.",al={"base da aliança pântano das mágoas","ponto de voo da aliança pântano","onde fica o acampamento da aliança"}},{q="Quem são os estranhos humanoides mutantes no pântano?",a="Eles são draeneis que ficaram presos em Azeroth após o colapso do Portal Negro. Isolados de seu mundo, a maioria enlouqueceu de desespero e se transformou nos hostis Os Perdidos. Um pequeno grupo de exilados Broken sãos refugiou-se a noroeste, em O Refúgio, preferindo a sobrevivência neutra à fúria cega.",al={"quem são os perdidos","o que é o refúgio","draeneis no pântano"}},{q="O que é a Penumbra das Mágoas?",a="A Penumbra das Mágoas é a densa faixa de terra pantanosa diretamente a leste do Poço de Lágrimas. Ela serve como área de patrulha para draconianos verdes de elite e crias que repelem violentamente os mortais a fim de proteger os segredos do Templo Submerso.",al={"área de dragões pântano das mágoas","dragões da penumbra das mágoas","draconianos verdes pântano"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris é um vasto e sufocante deserto que abrange os limites meridionais de Kalimdor, marcado por dunas de areia ondulantes e um calor abrasador. No seu coração fica Geringontzan, um entreposto comercial neutro operado pelos goblins do Cartel Bondebico. Além dos povoados movimentados, as dunas ocultam trolls da areia hostis, perigosas colmeias de silitídeos e o domínio oculto da revoada dragônica de bronze.",h="Tanaris é um vasto e sufocante deserto que abrange os limites meridionais de Kalimdor, marcado por dunas de...",kw={"cavernas do tempo","deserto","freebooters","geringontzan","nozdormu","sandfury","silitídeo","bondebico","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Sem grandes fortalezas da Aliança entre o Pântano Vadeoso e Feralas, o mestre de voo da Aliança na neutra Geringontzan funciona como um ponto de parada vital para viagens pelo sul de Kalimdor.",["faction:Horde"]="Geringontzan oferece aos batedores da Horda um conveniente entreposto comercial que conecta rotas da Aldeia Vento Livre e da Aldeia Mojache diretamente aos ermos infestados de silitídeos no extremo sul.",["profession:Herbalism"]="O calor seco nutre a esquiva Ignídea pelas dunas movediças, enquanto ruínas sombreadas e oásis úmidos fornecem abrigo para o valioso Lótus Roxo.",["profession:Mining"]="Os penhascos áridos e afloramentos rochosos ao redor das dunas oferecem ricas jazidas de Mítril, Veraprata, Ferro e Ouro, juntamente com depósitos dispersos de Tório Pequeno nas regiões mais profundas.",["race:Troll"]="Ver os Sandfury de Zul'Farrak oferece aos trolls um vislumbre cru de seus primos ancestrais, que sofreram mutações e se tornaram uma cultura brutal após serem isolados pela Cisão."},sec={{t="Um Mar de Dunas",b="Antes de a Grande Cisão despedaçar o mundo, esta extensão era uma selva exuberante habitada pelos primeiros taurens e reivindicada pelo Império Gurubashi. O cataclismo despojou a terra de sua copa verdejante, deixando uma vastidão estéril e castigada pelo sol. Ilhados pelas mudanças geográficas, os trolls locais se adaptaram, tornando-se a endurecida tribo Sandfury e esculpindo seu império isolado dentro da cidade murada de Zul'Farrak. Hoje, o solo do deserto é dominado por hienas, basiliscos e escorpitídeos, enquanto túneis subterrâneos serpenteiam sob a terra crestada."},{t="Empreendimento Goblin",b="Como Tanaris fica o mais perto da ilha natal de Kezan que o continente permite, o Cartel Bondebico estabeleceu um próspero empreendimento aqui. Do oásis murado de Geringontzan às docas costeiras do Porto de Bondebico, os goblins mantêm estrita neutralidade, acolhendo as moedas tanto da Aliança quanto da Horda. A paz deles é mantida pela força bruta de seus truculentos capangas, embora ameaças desonestas como os Southsea Freebooters fustiguem constantemente o transporte marítimo e os sítios de escavação ao longo do litoral."},{t="Mistérios Antigos e Perigos Crescentes",b="As areias escondem poderes muito mais antigos do que os impérios mortais. Nos confins orientais ficam as Cavernas do Tempo, o domínio ancestral de Nozdormu e de sua revoada dragônica de bronze, cujos draconídeos ocasionalmente podem ser vistos planando nas correntes térmicas do deserto. Ao sul, imponentes portões de pedra marcam o complexo titânico de Uldum. No entanto, um perigo mais sombrio se agita a partir de ninhos subterrâneos como a Fenda Hazzali e o Covil Nóxio, onde enxames rastejantes de silitídeos começaram a cavar para o exterior através das areias."}},faq={{q="Como viajo para Tanaris?",a="Os viajantes devem cruzar Mil Agulhas em direção à Chapada Cintilante. Uma passagem na montanha talhada através dos despenhadeiros na extremidade sul das salinas conduz diretamente ao deserto, deixando você imediatamente à vista das muralhas de Geringontzan.",al={"como chegar a tanaris","chegando a tanaris","entrada de tanaris"}},{q="Por que Geringontzan é neutra para ambas as facções?",a="Geringontzan é governada pelo Cartel Bondebico, cuja única lealdade é ao lucro. Para maximizar o comércio e proteger as rotas mercantis pelo deserto, os goblins impõem uma neutralidade rigorosa, empregando brutamontes para subjugar qualquer um tolo o bastante para iniciar brigas entre facções dentro dos muros da cidade.",al={"por que geringontzan é neutra","horda e aliança podem ir para geringontzan","neutralidade goblin geringontzan"}},{q="O que é Zul'Farrak?",a="Zul'Farrak é a capital fortificada no deserto dos trolls da areia Farraki. Isolada aqui desde que a Grande Cisão transformou a selva ancestral em um ermo árido, a tribo Sandfury tornou-se hostil a todos os forasteiros, guardando suas piscinas sagradas e santuários misteriosos contra aventureiros invasores.",al={"o que é zul'farrak","quem vive em zul'farrak","cidade dos trolls da areia"}},{q="O que são as criaturas insetoides que fazem ninhos pelo deserto?",a="As feras insetoides são silitídeos, escavadores coloniais monstruosos que constroem vastas colmeias, como a Fenda Hazzali e o Covil Nóxio. Sua presença emergente em Tanaris tem perturbado observadores como o Topógrafo Sênior Secamolha, lembrando os antigos horrores da Guerra das Areias Movediças.",al={"o que são os insetos em tanaris","colmeias de insetos em tanaris","silitídeos em tanaris"}},{q="O que há por trás das portas maciças de pedra no sul?",a="Os portões monumentais no Vale dos Vigilantes marcam a entrada para Uldum, uma lendária instalação de pesquisa e posse dos antigos titãs. A entrada permanece firmemente selada, guardada por sentinelas de pedra colossais e observada de longe por estudiosos e goblins curiosos.",al={"portões gigantes no sul de tanaris","portões de ruins of uldum","portão titânico de tanaris"}},{q="Quem habita o interior das Cavernas do Tempo?",a="As Cavernas do Tempo servem como covil ancestral da revoada dragônica de bronze e de seu aspecto, Nozdormu. A partir dessas profundezas ocultas e sinuosas, os dragões atemporais vigiam o fluxo da história, patrulhando ocasionalmente os céus bem acima das dunas do sul.",al={"história de cavernas do tempo","o que há em cavernas do tempo","dragões em tanaris"}}},fp="7,385,14.524.0,17.488.0,35.467.0,27.251.0,42.292.0,19.302.0,56.294.0,52.271.0,38.255.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste de Kalimdor. Cultivada pelos druidas no rescaldo da Terceira Guerra, seus galhos monumentais sustentam uma vasta natureza selvagem sob a penumbra e Darnassus, a capital dos elfos noturnos. No entanto, sob sua copa tranquila e banhada pelo luar, uma corrupção rastejante começou a se agitar.",h="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste...",kw={"circle of ancients","coroa da terra","darnassus","dolanaar","fandral guenelmo","rut'theran","umbravale","teldrassil","arvore do mundo"},ang={["class:Druid"]="Com Malfurion preso no Sonho Esmeralda, o Arquidruida Fandral Guenelmo lidera o Círculo Cenariano aqui, embora muitos druidas temam que Teldrassil tenha sido erguida às pressas.",["faction:Alliance"]="Teldrassil serve como o reduto mais ao norte da Aliança em Kalimdor, ancorando a comunicação naval e o comércio entre Darnassus e os reinos do continente.",["profession:Herbalism"]="Sem nenhum mineral ou minério, a copa verdejante da árvore compensa isso ao funcionar como um paraíso para coletores de Botão-da-paz, Folha-prata e Raiz-da-terra.",["race:NightElf"]="Esta árvore colossal é o novo recomeço do seu povo após a devastação do Monte Hyjal, mas a ausência das bênçãos dos Aspectos torna sua defesa um dever urgente."},sec={{t="Uma Copa Sobre o Mar",b="Teldrassil não é apenas uma árvore; é um ecossistema elevado que se ergue imponente em meio às águas do Veiled Sea. Seus galhos descomunais abrigam colinas ondulantes, rios caudalosos alimentados pelo orvalho da manhã, lagos enevoados e clareiras ancestrais densas. Em sua extremidade ocidental fica Darnassus, a grandiosa capital dos kaldorei. Na base de seu tronco monumental está a Vila de Rut'theran, conectada à copa por um portal místico e servindo como o principal porto da ilha."},{t="A Recusa dos Aspectos",b="Após o sacrifício de Nordrassil durante a Terceira Guerra e o misterioso desaparecimento do Shan'do Malfurion Tempesfúria no Sonho Esmeralda, o Arquidruida Fandral Guenelmo convenceu o Circle of Ancients a plantar uma substituta. Guenelmo esperava devolver aos kaldorei sua imortalidade perdida. No entanto, Nozdormu e os Aspectos Dragônicos consideraram a iniciativa arrogante e recusaram suas bênçãos. Sem essa proteção vital, o crescimento de Teldrassil sofreu com imperfeições não naturais."},{t="Uma Enfermidade Rastejante",b="Apesar de sua majestade exterior, a jovem Árvore do Mundo abriga uma enfermidade sombria. A fauna local se tornou violenta: tribos outrora pacíficas de furbolgs caíram na loucura, grells deformados se multiplicam nos túmulos e sátiros vis realizam ritos sombrios em recessos como a Pedra Vil. Mais abaixo, nas praias de Costa Negra, gigantes do mar, debulhadores e tartarugas encalham para fugir das águas contaminadas ao redor da árvore. Naturalistas e sentinelas agora trabalham freneticamente pela copa para identificar a sombra que lentamente estrangula seu novo lar."}},faq={{q="Por que Teldrassil foi cultivada?",a="Depois que Nordrassil foi devastada no final da Terceira Guerra, os elfos noturnos perderam sua imortalidade. O Arquidruida Fandral Guenelmo pressionou o Circle of Ancients e os druidas cenarianos a plantar uma nova Árvore do Mundo no mar, com o objetivo de restaurar o que seu povo havia perdido.",al={"por que foi feita","quem criou teldrassil","origem de teldrassil"}},{q="Por que Teldrassil não restaurou a imortalidade dos elfos noturnos?",a="Nordrassil concedia a imortalidade originalmente porque Nozdormu, o Atemporal, a abençoou. Quando Teldrassil foi erguida, Nozdormu julgou o desejo dos elfos noturnos como arrogante e se recusou a conceder sua bênção à nova árvore.",al={"imortalidade","por que nao sao imortais","bencao de nozdormu"}},{q="Como sair de Teldrassil?",a="Os viajantes devem atravessar Darnassus até o portal rosa nos Jardins do Templo, que os transporta para a Vila de Rut'theran na base do tronco. De Rut'theran, um navio navega pelo mar até Auberdine, no continente de Costa Negra, além das rotas de hipogrifos disponíveis.",al={"como sair","sair da arvore","barco de teldrassil"}},{q="Por que não há jazidas de mineração em Teldrassil?",a="Toda a zona se situa sobre os galhos vivos e a madeira de uma colossal Árvore do Mundo, em vez de rocha continental natural. Como não há crosta subterrânea rochosa, veios de metal ou depósitos de minério não se formam aqui, embora as ervas floresçam em grande abundância.",al={"onde tem cobre","sem minerio","mineracao em teldrassil"}},{q="O que está fazendo os furbolgs e as feras enlouquecerem?",a="Uma presença sinistra começou a se infiltrar nas raízes não abençoadas de Teldrassil. A doença corrompeu as águas e a flora locais, levando os outrora pacíficos lenhosos e a tribo furbolg Gnarlpine a uma agressividade frenética, enquanto remanescentes de sátiros cultivam ativamente a corrupção.",al={"furbolgs corrompidos","gnarlpine loucos","o que e a corrupcao"}},{q="O que é Umbravale?",a="Umbravale é um vale protegido e isolado nos galhos orientais de Teldrassil, ao redor da grande árvore Aldrassil. Ele serve como um santuário tranquilo onde os jovens elfos noturnos iniciam seu treinamento antes de se aventurarem pelo mundo afora.",al={"umbravale","area inicial","zona de aldrassil"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="Mil Agulhas",s="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul de Kalimdor. Tribos de taurens se apegam a povoados no topo de imponentes platôs para escapar de bandos agressivos de centauros, enquanto engenhoqueiros gnomos e goblins pilotam carros-foguete em alta velocidade pelo leito marinho seco da Chapada Cintilante.",h="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul...",kw={"vigia do rochedo chifre longo","pináculo da nuvem negra","xabu latafuso","aldeia vento livre","o grande elevador","totem sombrio","kravel barbakarvão","circuito da ilusão","relé","chapada cintilante","mil agulhas"},ang={["faction:Horde"]="O Grande Elevador conecta os Sertões à sua fortaleza na Aldeia Vento Livre, funcionando como uma fronteira estratégica ao sul contra os clãs de centauros e os taurens rebeldes.",["profession:Engineering"]="As planícies de sal são um destino de peregrinação para engenhoqueiros que procuram estudar combustível de foguete, peças de veículos e propulsão de alta velocidade no Circuito da Ilusão.",["race:Gnome"]="O Circuito da Ilusão, na Chapada Cintilante, é a principal chance de sua facção demonstrar a precisão e a elegância da engenharia gnômica contra as engenhocas grosseiras dos goblins.",["race:Tauren"]="A Aldeia Vento Livre ergue-se como um lembrete do quão alto seu povo precisou subir para escapar do massacre dos centauros, servindo também de ponto de apoio contra os traiçoeiros Totem Sombrio no Pináculo da Nuvem Negra."},sec={{t="Uma floresta de pedra",b="Antes que a Grande Cisão despedaçasse a antiga Kalimdor, este território era um cânion fluvial verdejante alimentado por cursos d'água continentais que fluíam em direção ao mar. O cataclismo rasgou o continente, empurrando o leito do rio acima do lençol freático e alterando seu curso até restarem apenas pedra seca e pináculos de arenito. Hoje, dezenas de esguias colunas cilíndricas erguem-se do fundo do cânion como uma floresta petrificada. Os taurens se estabeleceram nos cumes, estendendo pontes de corda precárias entre os picos para criar aldeias fora do alcance dos saqueadores centauros hostis que patrulham o fundo sombrio do desfiladeiro."},{t="Perigo nos platôs",b="No topo dos pináculos em forma de agulha, a vida está longe de ser pacífica. Na Aldeia Vento Livre, os taurens leais à Horda enfrentam não apenas serpentes aladas predatórias e mantícoras de Alcândora, mas também seus próprios parentes traiçoeiros: o belicoso clã Totem Sombrio, entrincheirado no Pináculo da Nuvem Negra. O Vigia do Rochedo Chifre Longo supervisiona a defesa do platô, em busca de combatentes corajosos para atacar os agitadores Totem Sombrio e proteger as frágeis pontes que conectam os picos. Ao norte, os enormes guinchos mecânicos d'O Grande Elevador transportam viajantes a partir dos Sertões Meridionais, embora cruzar o fundo do cânion continue sendo uma empreitada mortal."},{t="O Circuito da Ilusão",b="A sudeste, os paredões do cânion se abrem para a Chapada Cintilante, uma enorme e ressecada planície de sal situada abaixo do nível do mar. Nessa extensão árida e de uma brancura ofuscante, gnomos e goblins mantêm uma neutralidade incômoda ao redor do Circuito da Ilusão. Engenheiros rivais, Relé e Xabu Latafuso, disputam corridas de carros-foguete experimentais sobre o sal duro para decidir qual raça detém a superioridade tecnológica. Essa parada atrai canalhas, vigaristas como Kravel Barbakarvão e caçadores em busca dos resistentes escorpiões, tartarugas e basiliscos que vagam pela bacia causticante."}},faq={{q="Como Mil Agulhas recebeu esse nome?",a="A zona deve seu nome às dezenas de pináculos cilíndricos colossais de arenito que brotam do fundo do cânion. Esculpidas originalmente pelas correntes caudalosas dos rios antes da Grande Cisão, essas torres geológicas hoje parecem uma floresta de agulhas gigantes.",al={"por que se chama mil agulhas","origem dos pilares de agulha","história dos pináculos"}},{q="Como se desce até Mil Agulhas vindo dos Sertões?",a="Os viajantes utilizam O Grande Elevador, uma imensa estrutura com duas cabines operada por guardas da Horda na fronteira sul dos Sertões. Saltar da beirada é fatal, portanto é essencial aguardar a plataforma. Os viajantes da Aliança também podem chegar a pé pelo oeste, passando por Thalanaar, em Feralas.",al={"como chegar em mil agulhas","entrada d'o grande elevador","elevador para mil agulhas"}},{q="Por que os taurens vivem no topo dos platôs?",a="Os bandos de guerra centauros quase levaram os nômades taurens à extinção no passado. Construir postos avançados como a Aldeia Vento Livre no alto de pilares de pedra inacessíveis os manteve a salvo de investidas terrestres. Eles conectaram os platôs por meio de pontes pênseis de madeira, possibilitando viagens em grandes altitudes, muito acima dos predadores e saqueadores lá embaixo.",al={"por que taurens ficam nos pilares","história da aldeia vento livre","terreno elevado dos taurens"}},{q="O que é o Circuito da Ilusão?",a="O Circuito da Ilusão é um campo de provas de engenharia situado na planície de sal da Chapada Cintilante. Engenhoqueiros gnomos e goblins apostam corrida com carros experimentais movidos a foguete pelo leito plano de sal para resolver a rivalidade de longa data sobre qual raça constrói as melhores máquinas.",al={"pista da chapada cintilante","corrida de gnomos e goblins","pista de carro-foguete"}},{q="Qual é a presença do Totem Sombrio no cânion?",a="O clã Totem Sombrio ocupa o Pináculo da Nuvem Negra, um conjunto fortificado de torres rochosas que se opõe diretamente à Aldeia Vento Livre. Ao contrário das demais tribos taurens que juraram lealdade à Horda, o Totem Sombrio ataca ativamente outros taurens e conspira para tomar o controle dos platôs.",al={"totem sombrio em mil agulhas","taurens do pináculo da nuvem negra","taurens malignos de agulhas"}},{q="O que é a Chapada Cintilante?",a="A Chapada Cintilante é o leito de um vasto lago seco a leste dos platôs do cânion. A crosta de sal formou-se quando as antigas águas continentais evaporaram após a Cisão. O calor escaldante, o sal de brancura ofuscante e os predadores implacáveis transformam o local em um deserto inóspito, utilizado principalmente para testes de veículos em alta velocidade.",al={"deserto de sal","deserto branco de mil agulhas","deserto oriental"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="Penhasco do Trovão",s="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha fustigados pelo vento que se erguem sobre as pradarias de Mulgore. Fundada pelo Grande Chefe Caerne Casco Sangrento após unir as tribos nômades com a ajuda da Nova Horda, ela serve como o coração cultural, espiritual e mercantil de seu povo. Conectada por pontes de corda oscilantes e elevadores de madeira, a cidade oferece proteção contra saqueadores centauros e um santuário pacífico para viajantes por toda Kalimdor.",h="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha...",kw={"caerne casco sangrento","platô dos anciãos","elevadores","hamuul runa totem","platô dos caçadores","magatha temível totem","mulgore","poços das visões","platô dos espíritos","penhasco do trovão"},ang={["class:Druid"]="O Platô dos Anciãos serve como o santuário supremo de magia da natureza da Horda, liderado pelo Arquidruida Hamuul Runa Totem, o primeiro druida tauren instruído em milhares de anos.",["class:Shaman"]="O Platô dos Espíritos e os subterrâneos Poços das Visões oferecem um elo sereno onde os espíritos elementais e os espíritos dos ancestrais taurens são reverenciados e ouvidos.",["faction:Horde"]="Muito mais tranquilo e espiritual do que as fortificações austeras de Orgrimmar, o Penhasco do Trovão atua como o alicerce pastoral da influência da Nova Horda no sul de Kalimdor.",["race:Tauren"]="O Penhasco do Trovão representa a duramente conquistada união e o renascimento do seu povo após gerações de vida nômade e perseguição pelos centauros, sob o comando do Grande Chefe Caerne Casco Sangrento."},sec={{t="Um Refúgio Permanente",b="Por incontáveis gerações, os taurens viveram como andarilhos nômades por toda Kalimdor, travando uma luta brutal pela sobrevivência contra tribos vorazes de centauros. Essa era desesperadora terminou durante a Terceira Guerra, quando Caerne Casco Sangrento uniu forças com o Chefe Guerreiro Thrall. Juntos, os orcs e taurens repeliram as investidas dos centauros e garantiram as pastagens verdejantes de Mulgore. Para proteger o futuro deles, Caerne conduziu as tribos aliadas à segurança desses bastiões de pedra naturais, fundando o Penhasco do Trovão como o primeiro lar unificado e permanente dos taurens em séculos."},{t="Uma Cidade nas Nuvens",b="Estendendo-se por vários platôs elevados conectados por pontes de corda suspensas, o Penhasco do Trovão mescla com perfeição a arquitetura natural com a praticidade tauren. Os platôs centrais abrigam os movimentados mercados, o banco, a estalagem e o imponente poleiro de Mantícoras, enquanto três platôs especializados se ramificam sobre o abismo. O Platô dos Caçadores serve aos batedores e rastreadores da cidade; o Platô dos Anciãos abriga os guardiões da história e o Círculo Cenariano sob a liderança do Arquidruida Hamuul Runa Totem; e o Platô dos Espíritos é dedicado à comunhão espiritual, acolhendo xamãs, sacerdotes e as misteriosas cavernas subterrâneas conhecidas como os Poços das Visões."},{t="União Inquieta",b="Embora Caerne Casco Sangrento imponha imenso respeito de quase todas as tribos, governar um povo orgulhoso e recém-estabelecido traz seus atritos. Notavelmente, a tribo Temível Totem — liderada pela perspicaz e mordaz Matriarca Magatha Temível Totem — mantém uma presença sombria no Platô dos Anciãos. Magatha questiona abertamente os métodos conciliatórios de Caerne e sua lealdade às raças estrangeiras da Horda. Embora a paz se mantenha sob o olhar vigilante do chefe, fendas ideológicas murmuram entre as fogueiras do conselho sobre as planícies."}},faq={{q="Quem governa o Penhasco do Trovão?",a="O Grande Chefe Caerne Casco Sangrento governa o Penhasco do Trovão e lidera as tribos taurens unidas. Reverenciado por sua sabedoria, paciência e força colossal, Caerne fundou a cidade após se aliar à Horda de Thrall e expulsar os centauros de Mulgore.",al={"líder do penhasco do trovão","quem governa","chefe do penhasco do trovão","caerne"}},{q="Como se sobe até o Penhasco do Trovão?",a="Visitantes que chegam a pé ou em kodos precisam usar elevadores maciços com plataformas de madeira localizados nos lados sudoeste e nordeste do platô central. Como alternativa, a cidade conta com um poleiro de Mantícoras com rotas de voo por toda Kalimdor.",al={"elevador do penhasco do trovão","como entrar","entrada do penhasco do trovão","como subir"}},{q="Por que os taurens construíram no topo de platôs em vez de no chão?",a="Séculos de existência nômade foram marcados por ataques implacáveis de guerrilha desferidos por clãs agressivos de centauros. Os penhascos íngremes dos platôs de Mulgore oferecem defesa natural, protegendo as habitações, ferrarias e sábios anciãos dos taurens contra emboscadas terrestres, permitindo que eles se estabeleçam de forma permanente em paz.",al={"por que platôs","por que ficam em penhascos","penhascos do penhasco do trovão","posição elevada dos taurens"}},{q="Quais são os diferentes platôs da cidade?",a="A cidade abrange um platô central (dividido em níveis inferior, intermediário e superior) cercado por três platôs periféricos. O Platô dos Caçadores é dedicado aos guerreiros, caçadores e alojamentos de rastreamento. O Platô dos Anciãos é o lar de druidas, sábios e da facção Temível Totem. O Platô dos Espíritos abriga santuários para a Mãe Terra, instrutores de xamãs, sacerdotes e magos, e as cavernas dos Poços das Visões.",al={"áreas do penhasco do trovão","o que são os platôs","distritos do penhasco do trovão"}},{q="O que são os Poços das Visões?",a="Os Poços das Visões são cavernas subterrâneas sagradas ocultas sob o Platô dos Espíritos. Videntes, andarilhos espirituais e praticantes do arcano taurens se reúnem nessas águas serenas e envoltas em névoa para comungar com os elementos e interpretar presságios sobre o futuro de seu povo.",al={"poços das visões","caverna do platô dos espíritos","caverna do penhasco do trovão"}},{q="Quem é Magatha Temível Totem?",a="Magatha Temível Totem é a matriarca do formidável clã Temível Totem. Embora resida no Platô dos Anciãos e participe externamente do conselho de Caerne, ela é ferozmente tradicionalista, desconfia de forasteiros e desafia veladamente a postura branda da tribo Casco Sangrento em relação à Horda.",al={"magatha","matriarca","quem é o líder dos temível totem"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:tirisfal"] = {n="Clareiras de Tirisfal",s="Clareiras de Tirisfal é o assombroso território setentrional de Lordaeron, servindo agora como o coração do domínio de Grande Dama Sylvana Correventos e dos Renegados. Sob céus assolados e galhos apodrecidos jazem solares arruinados, criptas adormecidas e a vasta capital subterrânea de Cidade Baixa. Cercada pelo Flagelo irracional e por zelosos cruzados Escarlates, é um reino perigoso onde mortos-vivos de livre-arbítrio lutam pela própria sobrevivência.",h="Clareiras de Tirisfal é o assombroso território setentrional de Lordaeron, servindo agora como o coração do...",kw={"agamand","balnir","montalvo","plangemortis","renegados","clareiras","lordaeron","cruzada escarlate","sylvanas","tirisfal","tyr","cidade baixa"},ang={["class:Priest"]="Locais sagrados históricos como o Repouso de Faol — o túmulo do Arcebispo Alonsus Faol, fundador do Punho de Prata — ficam aqui, corrompidos pela morte e disputados entre fanáticos e sacerdotes da Sombra.",["faction:Alliance"]="Para as nações sobreviventes da Aliança, Tirisfal é um monumento trágico à queda de Lordaeron, repleto de túmulos profanados de antigos irmãos e irmãs na fé.",["faction:Horde"]="Tirisfal é o baluarte vital da Horda no norte dos Reinos do Leste, consolidando laços diplomáticos com os Renegados enquanto repele extremistas humanos e o Flagelo.",["race:Undead"]="Esta é a sua terra ancestral por duas vezes: o reino que você construiu em vida e o santuário precário que você precisa defender na morte-vida sob o comando de Lady Sylvanas."},sec={{t="Uma Terra no Crepúsculo",b="Outrora o fértil berço da humanidade, Clareiras de Tirisfal definhou sob a maldição da praga do Lich Rei. O sol raramente penetra a penumbra turva, lançando uma palidez doentia e eterna sobre bosques moribundos, plantações de abóbora abandonadas e colinas costeiras gélidas. Embora resquícios de antigas propriedades rurais como os Moinhos dos Agamand e a Fazenda dos Balnir ainda permaneçam, seus antigos donos foram em grande parte jogados em valas comuns ou reergueram-se como mortos inquietos. Apesar da devastação, uma resiliência sombria permeia a região, ancorada por povoados como Montalvo e pelo santuário enclausurado de Plangemortis, onde Renegados recém-despertados aprendem a suportar sua segunda vida."},{t="Uma Guerra em Duas Frentes",b="Embora Lady Sylvanas reivindique o domínio sobre a região a partir das subterrâneas Ruínas de Lordaeron, os Renegados continuam acossados por todos os lados. Lacaios residuais do Flagelo ainda infestam grotas, campos e criptas dilapidadas, inteiramente subservientes ao trono congelado de Northrend. A leste, a fanática Cruzada Escarlate fez do norte de Tirisfal seu principal baluarte, operando a partir do Monastério Escarlate. Zelosamente devotados ao extermínio de qualquer criatura morta-viva, viva ou não viva, seus postos avançados e patrulhas travam uma constante guerra de guerrilha contra batedores e viajantes civis Renegados."},{t="Ecos do Passado Ancestral",b="Muito antes de os reinos humanos coroarem seus primeiros monarcas, as Clareiras já carregavam um legado ancestral. Na antiga língua dos vrykul, 'Tirisfal' traduz-se como 'A Queda de Tyr', batizada após o heroico guardião titânico Tyr lutar até a morte contra horrores cósmicos colossais. Em eras posteriores, exilados elfos altaneiros tentaram colonizar brevemente estes bosques antes que energias sombrias nas profundezas da terra começassem a enlouquecê-los, motivando sua migração para o norte. Em séculos posteriores, a assembleia mortal secreta conhecida como o Conselho de Tirisfal escolheu esses bosques sombrios para conferir poder a Guardiões solitários, protegendo Azeroth de invasões demoníacas."}},faq={{q="Por que o céu é verde e a terra está apodrecendo?",a="Durante a Terceira Guerra, o Príncipe Arthas e o Flagelo espalharam a Praga da Morte-viva pelo Reino de Lordaeron. A peste mágica envenenou não apenas a população, mas o próprio solo, as árvores e a água, deixando as clareiras em um estado eterno de decadência sinistra e doentia.",al={"por que tirisfal está assolada","o que aconteceu com tirisfal","por que tirisfal está morrendo"}},{q="Qual é a diferença entre os Renegados e o Flagelo aqui?",a="Os Renegados são mortos-vivos que se libertaram da dominação telepática do Lich Rei após a Batalha do Monte Hyjal, escolhendo seguir Grande Dama Sylvana Correventos por vontade própria. O Flagelo que vagueia pelas fazendas e ruínas permanece como escravos irracionais atrelados às ordens do Lich Rei.",al={"renegados vs flagelo","por que zumbis atacam mortos-vivos","todos os mortos-vivos são maus"}},{q="Quem são os soldados de armadura vermelha que atacam viajantes?",a="Eles pertencem à Cruzada Escarlate, uma facção intransigente de antigos paladinos do Punho de Prata e sobreviventes. Convencidos de que todos os mortos-vivos são abominações irrecuperáveis que precisam ser purificadas pela espada e pelo fogo, eles executam tanto os lacaios irracionais quanto os Renegados de livre-arbítrio com ódio fanático.",al={"cruzada escarlate","humanos vermelhos","humanos do monastério"}},{q="De onde vem o nome Tirisfal?",a="A região é nomeada em homenagem ao guardião titânico Tyr. Segundo a lenda, Tyr tombou em combate contra horrores cósmicos nesta clareira. Na antiga língua dos vrykul, 'Tyr's Fall' evoluiu para o nome 'Tirisfal', e a mão de prata do guardião tornou-se um emblema profundamente enraizado na mitologia humana primitiva.",al={"significado de tirisfal","queda de tyr","origem de tirisfal"}},{q="Onde os Renegados recém-despertados começam sua jornada?",a="Renegados recém-despertados emergem das criptas do Sepulcro Sombrio dentro de Plangemortis, um povoado recluso situado no sudoeste de Tirisfal. Lá, administradores e executores avaliam se os mortos erguidos possuem a sanidade e a lealdade necessárias para servir à Dama Sombria.",al={"área inicial dos mortos-vivos","onde fica plangemortis","área inicial dos renegados"}},{q="Como os viajantes saem de Tirisfal para outros continentes?",a="Uma grande torre de zepelim operada por goblins fica na encosta ao sul de Montalvo, logo nos arredores das Ruínas de Lordaeron. Essas aeronaves oferecem transporte direto e regular pelos mares até Orgrimmar, em Kalimdor, e o Acampamento Grom'gol, na Selva do Espinhaço.",al={"zepelins de tirisfal","como ir para orgrimmar","como ir para selva do espinhaço"}}},fp="15,403,18.637.0,19.603.0,26.621.0,42.269.0,65.287.0,53.289.0,39.297.0,53.269.0,53.247.0"}
P.entries["zone:undercity"] = {n="Cidade Baixa",s="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza dos Renegados. Escavada originalmente a partir de antigas criptas reais e masmorras pelo Flagelo, foi tomada por Grande Dama Sylvana Correventos e transformada em um impenetrável santuário subterrâneo. Hoje, serve como a sede do poder dos Renegados e o bastião vital da Horda no norte dos Reinos do Leste.",h="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza...",kw={"boticarium","arthas","renegados","lordaeron","flagelo","sylvanas","terenas","tirisfal","cidade baixa","varimatras"},ang={["faction:Horde"]="Como a principal fortaleza da Horda nos Reinos do Leste, Cidade Baixa garante conexões diretas por zepelim com Durotar e o Acampamento Grom'gol.",["race:Human"]="Sob o solo do seu reino ancestral devastado jaz uma sombria perversão das criptas reais de Lordaeron, ocupada pelos cadáveres ambulantes dos seus antigos irmãos.",["race:Orc"]="Nas profundezas destas mesmíssimas masmorras, o lendário Chefe de Guerra Orgrim Martelo da Perdição já esteve aprisionado pela Aliança de Lordaeron antes de realizar sua fuga histórica.",["race:Undead"]="A Cidade Baixa é o seu santuário soberano e lar, esculpido por suas próprias mãos depois de quebrar o domínio de ferro do Lich Rei sobre a sua mente."},sec={{t="De Criptas Reais a Reduto do Flagelo",b="Muito antes de a peste assolar Lordaeron, as catacumbas, masmorras e esgotos sob o palácio eram conhecidos coletivamente como Cidade Baixa. O local abrigava os túmulos da nobreza, as prisões mais profundas do reino — onde o antigo Chefe de Guerra Orgrim Martelo da Perdição já esteve preso antes de fugir — e os habitantes mais indigentes da região. Quando Arthas Menethil assassinou o Rei Terenas e devastou a capital em 20 ADP, o príncipe ordenou que seus servos mortos-vivos escavassem e expandissem as passagens subterrâneas em uma sede fortificada para o domínio do Flagelo."},{t="Ascensão dos Renegados",b="O Flagelo nunca viu sua capital sombria concluída. Quando os poderes do Lich Rei diminuíram após a batalha do Monte Hyjal, Grande Dama Sylvana Correventos libertou-se do controle mental, levando consigo milhares de mortos-vivos. Ela atraiu Arthas para uma emboscada e o expulsou de volta para Northrend. Após uma violenta guerra civil tripartite contra remanescentes do Flagelo, Senhores do Medo e a resistência humana, Sylvanas reivindicou as catacumbas inacabadas. Dando ao seu povo o nome de Renegados, ela supervisionou anos de trabalho árduo para concluir a vasta cidade subterrânea."},{t="Arquitetura dos Condenados",b="Cidade Baixa é organizada em anéis concêntricos divididos em bairros funcionais. Em seu coração fica o Distrito Comercial, conectado por grandes elevadores às ruínas do palácio acima. Ao seu redor estão o Distrito Bélico, o Distrito dos Ladinos, o Distrito da Magia e o tóxico Boticarium, onde a Real Sociedade de Boticários prepara pestes virulentas em canais cheios de lodo verde. Mais abaixo ainda fica o Distrito Real, onde a Rainha Banshee governa ao lado de seu comandante Senhor do Medo, Varimatras, protegida por legiões de imponentes abominações."}},faq={{q="O que era Cidade Baixa antes de os mortos-vivos a tomarem?",a="Sob o palácio de Lordaeron ficavam as antigas criptas da realeza humana, juntamente com o complexo carcerário e a vasta rede de esgotos da cidade. Ali ficavam prisioneiros de guerra, incluindo Orgrim Martelo da Perdição, bem como cidadãos desprovidos vivendo nas sombras subterrâneas. Após saquear a capital, o Príncipe Arthas começou a transformar essas catacumbas em uma fortaleza do Flagelo antes de Sylvanas tomá-las.",al={"origens de cidade baixa","o que era cidade baixa originalmente","historia dos esgotos de lordaeron"}},{q="Por que a cidade é construída no subsolo em vez de na superfície?",a="A cidade de Lordaeron na superfície foi completamente arruinada durante a Terceira Guerra, tornando difícil defendê-la contra a Cruzada Escarlate, as forças do Flagelo e os sobreviventes da Aliança. Os túneis subterrâneos ofereciam fortificação natural, pontos de estrangulamento e discrição, permitindo aos Renegados concluir a construção inicial do Flagelo e prosperar sem serem vistos.",al={"por que morar no subsolo","por que nao reconstruir lordaeron","por que cidade baixa sob as ruinas"}},{q="Quem governa Cidade Baixa?",a="A cidade é governada por Grande Dama Sylvana Correventos, a Rainha Banshee e Rainha dos Renegados. Ela lidera a partir do Distrito Real, guardada por sentinelas reais dos Renegados e por seu tenente Senhor do Medo subjugado, Varimatras.",al={"quem e o lider de cidade baixa","governante de cidade baixa","quem comanda cidade baixa"}},{q="O que é o memorial do Rei Terenas nas ruínas acima?",a="Acima dos elevadores principais da cidade encontra-se um memorial de pedra para o falecido Rei Terenas Menethil II. Não contém seu corpo, pois seus restos foram cremados e suas cinzas descartadas durante a ressurreição de Kel'Thuzad. Humanos sobreviventes da Aliança esculpiram bravamente o monumento em meio às ruínas para que a memória do último verdadeiro rei de Lordaeron perdurasse.",al={"tumulo do rei terenas","tumulo na sala do trono de lordaeron","quem construiu o tumulo acima de cidade baixa"}},{q="O que são os barulhos estranhos na sala do trono de Lordaeron?",a="Na sala do trono em ruínas acima dos elevadores de Cidade Baixa, ecos espectrais do passado ainda permanecem. Os visitantes que ficam no centro podem ouvir tênues sons fantasmagóricos: os sinos festivos e as pétalas de rosa do retorno de Arthas, as palavras de aviso do profeta Medivh e a conversa final entre o Rei Terenas e seu filho parricida.",al={"sons de fantasmas na sala do trono","sussurros na sala do trono","vozes na sala do trono de lordaeron"}},{q="Por que os Renegados permitem outros membros da Horda aqui?",a="Os Renegados formaram uma aliança de conveniência com a Horda do Chefe de Guerra Thrall para garantir sua sobrevivência, cercados como estão por fanáticos zelotes da Cruzada Escarlate e legiões do Flagelo. Embora as raças vivas da Horda achem os vapores tóxicos e os rios alquímicos sufocantes, emissários e viajantes têm acesso liberado para cultivar laços diplomáticos e militares.",al={"por que ha orcs em cidade baixa","horda em cidade baixa","por que cidade baixa faz parte da horda"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Cratera Un’Goro",s="A Cratera Un'Goro é uma selva primordial e rebaixada, aninhada entre os ermos áridos de Tanaris e Silithus. Dominada por dinossauros errantes, elementais vivos e um vulcão central, esta exuberante caldeira está repleta de antigas relíquias dos Titãs e cristais de poder cujas origens continuam sendo um profundo mistério.",h="A Cratera Un'Goro é uma selva primordial e rebaixada, aninhada entre os ermos áridos de Tanaris e Silithus.",kw={"demossauro","pico penacho de fogo","terras dos deuses","lakkari","refúgio do marshal","cristais de poder","torwa mateiro","ungoro","cratera ungoro"},ang={["class:Druid"]="Druidas do Círculo Cenariano estudam o ecossistema isolado de Un'Goro e colhem seu solo rico para propagar Erva-da-manhã, buscando compreender a força vital pura e indômita que sustenta a caldeira.",["faction:Alliance"]="Naturalistas da Aliança se reúnem em torno de Williden Marshal e J.D. Collie no Refúgio do Marshal, correndo contra o tempo para decifrar os pilares dos Titãs enquanto protegem os pesquisadores de Darnassus que coletam amostras de solo.",["faction:Horde"]="Aventureiros da Horda costumam chegar por Tanaris para testar sua perícia contra lendários demossauros e ajudar os herboristas de Penhasco do Trovão a cultivar Erva-da-manhã a partir da terra primitiva de Un'Goro.",["profession:Herbalism"]="A rica umidade da bacia sustenta uma flora rara, servindo como um dos poucos lugares de Kalimdor onde Erva-cega, Folha-de-sonho e Sonsona-dourada florescem juntas, ao lado da Ignídea nas encostas do vulcão.",["profession:Mining"]="As paredes íngremes da cratera e os rochedos do Pico Penacho de Fogo são densos em Depósitos de Mícrio e Ricas Veias de Tório, tornando a área um destino de primeira linha para minérios nobres."},sec={{t="As Terras dos Deuses",b="Espremida entre extensões desérticas, a Cratera Un'Goro desafia a geografia do sul de Kalimdor. Antigos registros de elfos noturnos que detalham a Guerra das Areias Movediças observam que os insetoides Qiraji foram repelidos nas bordas da cratera, incapazes de penetrar o que em sua língua chamavam de \"Terras dos Deuses\". Estudiosos teorizam que a caldeira serviu como campo de testes ou antiga morada dos Titãs durante a formação de Kalimdor. Pilares de pedra erguem-se pelas cristas, zumbindo com energia, enquanto formações de cristais azuis, vermelhos, verdes e amarelos brotam pela terra primeva."},{t="Um ecossistema selvagem",b="Un'Goro não abriga cidades, vilarejos ou sociedades humanoides nativas. Em vez disso, a vida floresce em um estado indômito e primitivo. Demossauros ápices rondam as planícies do Terroral, petalisangues predatórias atacam nos pântanos, e viscos rastejam pelos poços de piche de Lakkari. No coração da cratera ergue-se o Pico Penacho de Fogo, um cume vulcânico ativo repleto de elementais do fogo hostis liderados pela entidade Blazerunner. Para exploradores e esfoladores, a bacia oferece uma riqueza natural inigualável — incluindo os cobiçados couros de demossauro —, contanto que se sobreviva à cadeia alimentar."},{t="Refúgio do Marshal",b="A presença civilizada na cratera limita-se quase inteiramente ao Refúgio do Marshal, um acampamento elevado situado nos penhascos ao norte. Liderada por Williden Marshal, uma expedição de cientistas, naturalistas e caçadores de fortunas tentou catalogar os tesouros da bacia, apenas para ser castigada pela fauna monstruosa e empurrada para terrenos elevados. Hoje, o refúgio serve como uma base de operações cercada para viajantes intrépidos que estudam os misteriosos cristais de poder da cratera, mapeiam a atividade vulcânica e mantêm um olho vigilante sobre os enxames de silitídeos que avançam pelas cristas ao sul."}},faq={{q="Como se entra na Cratera Un'Goro?",a="Os viajantes podem entrar por meio de rampas naturais que descem pelas paredes da cratera: uma acessível a partir do canto sudoeste de Tanaris, perto do Vale Moitagulhas, e outra que desce a partir do nordeste de Silithus. Embora aventureiros imprudentes às vezes saltem dos penhascos, a queda é fatal sem auxílio mágico. O Refúgio do Marshal, ao norte, oferece conexões de voo para Geringontzan e Forte Cenariano.",al={"como entrar em ungoro","entrada de ungoro","como chegar a cratera ungoro"}},{q="Para que servem os cristais de poder coloridos?",a="Espalhados pelo chão da selva estão Cristais de Poder vermelhos, azuis, verdes e amarelos. Com a orientação da pesquisadora gnoma J.D. Collie no Refúgio do Marshal, os exploradores podem decifrar instruções para usar esses cristais nos Pilares do Norte, do Leste e do Oeste. Combinar cores específicas nos pilares apropriados canaliza energias latentes dos Titãs para criar amuletos defensivos ou restauradores.",al={"cristais de ungoro","cristais vermelhos azuis verdes amarelos ungoro","pilares de poder"}},{q="Por que Un'Goro é exuberante mesmo cercada por desertos?",a="Estudiosos acreditam que a vitalidade incomum de Un'Goro é artificial, originada dos Titãs que moldaram o mundo. Condutos titânicos, a atividade geotérmica vulcânica e aquecida do Pico Penacho de Fogo e a antiga energia de linhas de meridiano nutrem um ecossistema isolado e hiperacelerado que resiste às condições áridas das vizinhas Tanaris e Silithus.",al={"por que ungoro e uma selva","conexao de ungoro com o deserto","como ungoro tem plantas"}},{q="Por que os Qiraji chamavam este lugar de \"Terras dos Deuses\"?",a="De acordo com tábuas traduzidas da Guerra das Areias Movediças, os enxames de insetos interromperam seu avanço no limiar da cratera. A Geologist Larksbane, que traduziu o relato, vincula o nome a teorias de que os Titãs um dia habitaram a cratera, e se pergunta se o próprio Aman'Thul vigiava as Terras dos Deuses.",al={"significado de terras dos deuses","qiraji ungoro","por que silitideos nao tomaram ungoro"}},{q="Para que serve o Solo de Un'Goro?",a="Montes de terra rica e potente repousam por toda a bacia da cratera. Quando coletada, essa terra pode ser combinada com sementes de Tharlendris em um Bornal de Sempre-viva para cultivar Erva-da-manhã, uma erva mística intensamente procurada por pesquisadores em Penhasco do Trovão, Darnassus e no Círculo Cenariano.",al={"amostra de solo de ungoro","o que o solo de ungoro faz","solo de erva-da-manha"}},{q="Há algum assentamento humanoide ou masmorra aqui?",a="Não há instâncias, masmorras ou sociedades humanoides nativas na Cratera Un'Goro. O único assentamento permanente é o Refúgio do Marshal, um pequeno entreposto de expedição na borda norte. Além de caçadores eremitas isolados ou exploradores perdidos, o resto da caldeira é inteiramente selvagem.",al={"masmorras de ungoro","quem vive em ungoro","humanoides em ungoro"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.274.0"}
P.entries["zone:wailing"] = {n="Caverna Ululante",s="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico de nascentes e fissuras subterrâneas que recebeu esse nome devido ao silvo sinistro do vapor represado. O que começou como um nobre esforço druídico para revitalizar a savana crestada pelo sol de Kalimdor transformou-se em um submundo distorcido e venenoso. As cavernas agora fervilham com uma fauna deturpada e discípulos decaídos corrompidos por um pesadelo profundo e antinatural.",h="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico...",kw={"desvirtuado","druidas da presa","pesadelo esmeralda","lady sucurina","lorde cobrahn","lorde pítias","lorde serpentis","oásis das águas claras","mutanus","naralex","verdan"},ang={["class:Druid"]="Para druidas tanto da tradição cenariana quanto da senda tauren, as cavernas são um aviso trágico dos perigos dentro do Sonho Esmeralda e um dever solene de purgar seus irmãos decaídos, os Druidas da Presa.",["race:NightElf"]="Naralex era uma figura reverenciada entre os druidas elfos noturnos, e a tragédia de sua corrupção pelo Pesadelo Esmeralda representa uma catástrofe dolorosa para seus semelhantes do outro lado do mar.",["race:Tauren"]="As águas retorcidas ameaçam os frágeis oásis que sustentam a vida pelos Sertões, tornando a purificação das nascentes vital para as tribos de Mulgore e da Encruzilhada."},sec={{t="Uma Nobre Visão Tornada Venenosa",b="O druida elfo noturno Naralex originalmente descobriu este vasto sistema de águas e concebeu um plano ambicioso: ao abrir um canal direto para o Sonho Esmeralda, ele drenaria pura essência vital primordial através das nascentes subterrâneas, transformando os ressequidos Sertões de volta em um paraíso verdejante e próspero. Nas profundezas das cavernas, Naralex entrou em comunhão com o Sonho, ancorado por seus leais acólitos. Tragicamente, em vez de extrair vitalidade pura, a mente adormecida do druida tocou o Pesadelo Esmeralda. A corrupção purulenta apoderou-se dele instantaneamente, transformando seu canal de boas intenções em uma válvula que despeja veneno e loucura nos cursos d'água subterrâneos."},{t="Os Druidas da Presa",b="À medida que a energia sombria do Pesadelo irradiava da forma indefesa de Naralex, seus pupilos sucumbiram à loucura. Abandonando a sabedoria tranquila do Círculo Cenariano, eles formaram os fanáticos Druidas da Presa. Assumindo formas reptilianas, os líderes da seita — Lady Sucurina, Lorde Cobrahn, Lorde Pítias e Lorde Serpentis — agora abraçam a mutação venenosa das cavernas em vez de combatê-la. Eles protegem ativamente seu mestre adormecido de qualquer interferência externa, acreditando que esse crescimento retorcido é a verdadeira evolução da natureza."},{t="O Pesadelo Feito Carne",b="Quebrar o domínio dos Druidas da Presa não salva Naralex automaticamente. Quando seus discípulos restantes não corrompidos iniciam o ritual para despertá-lo suavemente de seu transe em Dreamer's Rock, o subconsciente agitado do elfo adormecido expurga violentamente seu mais profundo terror. A criatura que irrompe — um murloc monstruoso e distorcido chamado Mutanus, o Devorador — é a manifestação física dos piores pesadelos de Naralex. Apenas derrotando essa abominação o canal para o Pesadelo pode ser rompido, permitindo que Naralex acorde, assuma uma forma aviária e fuja em voo das cavernas maculadas."}},faq={{q="Por que se chama Caverna Ululante?",a="A caverna recebe esse nome devido aos uivos lamentosos ouvidos por todos os túneis. Esses sons são produzidos naturalmente quando saídas subterrâneas de vapor e rajadas de vento de alta pressão forçam passagem por fissuras estreitas na rocha calcária.",al={"por que caverna ululante","origem do nome","por que elas uivam"}},{q="O que fez com que as feras de dentro se tornassem 'desvirtuadas'?",a="Quando Naralex caiu sob o domínio do Pesadelo Esmeralda, as energias oníricas maculadas vazaram diretamente para as nascentes subterrâneas. Beber e viver nessas águas contaminadas causou mutações nos raptores, crocoliscos e serpentes naturais, transformando-os em variantes 'desvirtuadas' antinaturais.",al={"corrupção desvirtuada","por que os raptores mutacionam","origem das feras desvirtuadas"}},{q="Quem são os Druidas da Presa?",a="Eles já foram os devotos acólitos elfos noturnos e taurens de Naralex. Corrompidos junto com ele pelo Pesadelo, suas mentes se despedaçaram e distorceram suas artes druídicas em adoração a serpentes e veneno, adotando títulos como Cobrahn, Pítias e Sucurina.",al={"druidas da presa","história dos druidas da presa","quem é serpentis"}},{q="Por que o último chefe é um murloc gigante chamado Mutanus?",a="Mutanus surge durante a tentativa de despertar Naralex. Sua natureza e conexão com o druida adormecido são reveladas conforme o ritual se desenrola.",al={"por que mutanus murloc","o que é mutanus","história do último chefe"}},{q="O que acontece após Mutanus ser derrotado?",a="A tentativa dos discípulos de despertar Naralex continua após o confronto. O destino do druida é revelado ao final do ritual.",al={"despertar naralex","desfecho de naralex","o que acontece com naralex"}},{q="Quem vive na caverna acima da entrada da masmorra?",a="Instalados dentro da cavidade ocular de rocha semelhante a um crânio da caverna estão lealistas do Círculo Cenariano, incluindo Nalpak e Ebru. Eles procuram viajantes corajosos para coletar Deviate Hides e purificar a corrupção antes que ela engula completamente os Sertões.",al={"caverna acima da entrada","npcs no olho do crânio de serpente","quem são nalpak e ebru"}}},fp="15,426,31.680.0,22.528.0,24.592.1,37.248.0,50.267.0,31.252.0,51.137.1,39.130.1,52.232.0"}
P.entries["zone:westernplaguelands"] = {n="Terras Pestilentas Ocidentais",s="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob uma névoa tóxica e legiões de mortos-vivos. Embora os caldeirões de Kel'Thuzad tenham arruinado as fazendas e cidades da região, o solo ainda se apega tenazmente à vida. A Aurora Argêntea, a Aliança, os Renegados e a Cruzada Escarlate travam campanhas desesperadas por seus campos assolados.",h="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob...",kw={"andorhal","o baluarte","castro das flechas","caldeirões","acampamento ventogelante","amparo","bastilha mardenforte","scolomântia","tumba de uther","terras pestilentas ocidentais"},ang={["class:Paladin"]="Os campos profanados de Lordaeron são uma prova sombria para guerreiros sagrados, oferecendo peregrinação à Tumba de Uther, bem como uma guerra justa contra os horrores de Scolomântia e os fanáticos corrompidos de Amparo.",["faction:Alliance"]="O Acampamento Ventogelante serve como a guarnição avançada da Aliança, onde o Comandante Ashlam Punhovalor lidera campanhas para neutralizar os caldeirões da peste e vingar as cidades caídas de Lordaeron.",["faction:Horde"]="O Baluarte marca a fronteira da soberania dos Renegados; a partir daqui, a Horda avança para o leste para neutralizar comandantes do Flagelo e combater os fanáticos Escarlates ao longo de seu flanco vulnerável.",["profession:Herbalism"]="A mácula persistente faz da região um dos poucos lugares onde flora rara e perigosa, como Pragônia e Lágrimas-de-arthas, consegue criar raízes entre os pinheirais assolados."},sec={{t="O Celeiro de Lordaeron",b="Antes da Terceira Guerra, esta terra era um corredor verdejante de fazendas que se estendia a leste das Clareiras de Tirisfal até o Lago das Flechas. Amparo governava a administração do norte a partir da Bastilha Mardenforte, enquanto a vasta cidade de Andorhal orquestrava o armazenamento e a exportação de grãos por todo o reino. Esse papel agrícola crucial tornou a região o alvo principal de Kel'Thuzad. Ao introduzir a Peste da Morte-viva diretamente nas remessas de grãos em Andorhal, a Seita dos Malditos transformou o sustento de Lordaeron em sua ruína."},{t="Uma Terra Sob Cerco",b="Para envenenar o solo de forma permanente, o Flagelo ergueu quatro enormes caldeirões da peste pelas maiores propriedades agrícolas: Campo Pedravil, Lágrimas de Dalson, o Antro Repelente e a Aridez de Garrão. Hoje, monstruosos Senhores dos Caldeirões mantêm essas cubas nocivas, bombeando névoa venenosa na atmosfera. As árvores ao redor se retorcem com crescimentos tumorais inchados, e animais selvagens corrompidos vagam descontrolados pela vegetação. Sob o Castro das Flechas, no Lago das Flechas, o Umbromestre Gandling treina necromantes dentro de Scolomântia, agravando a ameaça dos mortos-vivos."},{t="Facções Divididas",b="Apesar da onipresença do Flagelo, várias facções mantêm posições disputadas. A Cruzada Escarlate controla a fortaleza de Amparo no norte, expurgando com zelo raivoso qualquer coisa que considerem contaminada. Ao sul, as forças da Aliança se organizam a partir do Acampamento Ventogelante, enquanto os Renegados defendem suas fronteiras no Baluarte. Mediando e liderando a luta contra os caldeirões dos mortos-vivos está a neutra Aurora Argêntea, que ajuda campeões de ambas as facções e guarda a Tumba de Uther — o último solo verdadeiramente santificado da região."}},faq={{q="Por que a Peste atingiu esta área com tanta força?",a="Andorhal era o centro de distribuição agrícola do norte de Lordaeron. Kel'Thuzad atacou intencionalmente o suprimento regional, infectando silos de grãos e instalando enormes caldeirões da peste em quatro grandes propriedades rurais para espalhar rapidamente a morte-viva por meio de remessas de alimentos por todo o reino.",al={"por que as terras pestilentas ocidentais foram assoladas","o que aconteceu com andorhal","por que caldeirões aqui"}},{q="Quem controla Amparo no norte?",a="Amparo e sua fortaleza, a Bastilha Mardenforte, são governadas pela Cruzada Escarlate. Embora originalmente tenha sido um centro administrativo regional de Lordaeron, os fanáticos agora executam qualquer forasteiro que se aproxime de suas fronteiras, vendo todos os não membros da cruzada com suspeita.",al={"facção de amparo","quem vive na bastilha mardenforte","amparo é amigável"}},{q="Onde os jogadores da Aliança e da Horda podem encontrar postos avançados seguros?",a="A Aliança mantém o Acampamento Ventogelante perto da fronteira sul com as Montanhas de Alterac, oferecendo um mestre de voo e aliados da Aurora Argêntea. A Horda opera a partir d'O Baluarte, na fronteira oeste com as Clareiras de Tirisfal.",al={"onde ficam as rotas de voo","acampamento da horda tpo","acampamento da aliança tpo"}},{q="Qual é o objetivo dos caldeirões da peste nos campos?",a="Erigidos pela Seita dos Malditos no Campo Pedravil, nas Lágrimas de Dalson, n'O Antro Repelente e na Aridez de Garrão, esses caldeirões bombeiam vapores constantes da peste para o ar e o solo. Agentes da Aurora Argêntea recrutam aventureiros para abater os Senhores dos Caldeirões e neutralizar as misturas tóxicas.",al={"o que são os caldeirões","objetivo dos caldeirões","caldeirão de pedravil"}},{q="O que é Scolomântia e onde ela fica?",a="Scolomântia é uma academia subterrânea de necromancia administrada pelo Flagelo e pela Seita dos Malditos. Ela fica escondida sob as ruínas do Castro das Flechas, uma fortaleza insular situada nas águas a sudeste do Lago das Flechas.",al={"localização de scolomântia","onde fica scolomântia","masmorra castro das flechas"}},{q="Alguma parte das Terras Pestilentas Ocidentais permaneceu pura?",a="A Tumba de Uther, localizada na Colina do Pesar perto do limite sul da zona, permanece totalmente sagrada e intocada pela praga. Ela se ergue como um memorial consagrado ao falecido Alto-general Uther, o Arauto da Luz, e à perdida Ordem do Punho de Prata.",al={"solo sagrado em tpo","a tumba de uther está limpa","a tumba de uther é segura"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:westfall"] = {n="Cerro Oeste",s="Outrora o fértil celeiro do Reino de Ventobravo, Cerro Oeste ruiu, tornando-se um território castigado pelo vento, negligenciado e infestado de foras da lei. Privados do apoio oficial da coroa e de guarnições militares, os colonos sobreviventes apegam-se a suas fazendas enquanto a Irmandade Défias aperta o cerco a partir da cidade mineradora abandonada de Arroio da Lua.",h="Outrora o fértil celeiro do Reino de Ventobravo, Cerro Oeste ruiu, tornando-se um território castigado pelo...",kw={"minas mortas","defias","golem de colheita","milicia","arroio da lua","saldanha","morro da sentinela","mantoforte","vancleef","cerro oeste"},ang={["class:Rogue"]="A guerra nas sombras em Cerro Oeste coloca os espiões da AVIN diretamente contra os batedores astutos, ladrões e assassinos da Irmandade Défias.",["faction:Alliance"]="Sem a Milícia do Povo defendendo o Morro da Sentinela, a Irmandade Défias controlaria os acessos do sul diretamente até a Floresta de Elwynn.",["profession:Cooking"]="Os colonos acuados na Fazenda dos Saldanha se viram com as duras feras locais, ensinando aos viajantes como preparar o reconfortante prato básico conhecido como Ensopado de Cerro Oeste.",["race:Human"]="Cerro Oeste é um doloroso reflexo da decadência política de Ventobravo; os fazendeiros famintos na terra foram abandonados pela mesma nobreza que trabalhavam duro para alimentar."},sec={{t="Uma terra deixada para trás",b="Por gerações, Cerro Oeste alimentou o Reino de Ventobravo. Seus campos ondulantes e plantações de trigo floresceram até que o rescaldo da Segunda Guerra trouxe exaustão financeira e negligência política. Quando o reino concentrou seus recursos em outras partes e deixou de manter suas guarnições, o território ficou em pousio. Hoje, pastos áridos, rajadas costeiras uivantes, golens de colheita rebeldes e invasões de gnomos Pata-do-rio tornam a sobrevivência diária uma provação constante para os poucos obstinados que se recusam a abandonar suas terras."},{t="A ascensão da Irmandade",b="O colapso de Cerro Oeste acelerou quando a Guilda dos Pedreiros, tendo seu pagamento negado pela reconstrução de Ventobravo, iniciou uma revolta aberta. Declarados foras da lei e exilados sob o comando de Edwin VanCleef, os pedreiros se reconstituíram como a Irmandade Défias. Eles reivindicaram Cerro Oeste como sua fortaleza, queimando campos de fazendeiros teimosos, salgando o solo e tomando minas abandonadas. Operando a partir da cidade-fantasma de Arroio da Lua, a Irmandade agora governa a maior parte do campo em tudo, exceto no nome."},{t="A Milícia do Povo",b="Com a Casa dos Nobres ignorando a crise de Cerro Oeste, os habitantes locais assumiram a própria defesa. Com base no posto fortificado do Morro da Sentinela, Miguel Mantoforte organizou a Milícia do Povo — uma força voluntária que tenta manter a linha de frente contra gnolls e bandidos. Sem soldados formais nem suprimentos de Ventobravo, a Milícia depende de aventureiros errantes para conter o avanço dos Défias e proteger as fazendas remanescentes."},{t="A conspiração das Minas Mortas",b="A verdadeira magnitude da ameaça Défias jaz oculta sob a superfície. Nas profundezas dos poços de ouro abandonados das Minas Mortas, sob Arroio da Lua, Edwin VanCleef reuniu um exército de degoladores, goblins e renegados. Longe de ser mero banditismo, a Irmandade está construindo um colossal encouraçado de ferro projetado para navegar pela costa e bombardear Ventobravo diretamente."}},faq={{q="Por que tantas fazendas estão abandonadas em Cerro Oeste?",a="Ventobravo retirou suas guarnições militares quando o custo de manutenção se tornou alto demais, deixando a região desprotegida. Pouco depois, a Irmandade Défias assumiu o controle do campo, expulsando colonos, queimando plantações e reprogramando vigias mecânicos de colheita em sentinelas letais.",al={"fazendas abandonadas","por que cerro oeste esta morto","por que em pousio"}},{q="Por que Ventobravo não envia tropas para ajudar Cerro Oeste?",a="O tesouro do reino está esgotado, e a Casa dos Nobres considera as ameaças em outras terras como prioridades maiores. Além disso, manipulações na corte privaram silenciosamente Cerro Oeste de atenção e suprimentos, forçando os moradores locais a se defenderem sozinhos.",al={"por que nao ha exercito de ventobravo","onde estao os guardas","ajuda de ventobravo"}},{q="O que é a Milícia do Povo?",a="A Milícia do Povo é uma organização defensiva de voluntários organizada por Miguel Mantoforte no Morro da Sentinela. Como a coroa se recusou a enviar soldados a Cerro Oeste, os fazendeiros e colonos restantes se uniram para combater a Irmandade Défias e os gnolls Pata-do-rio.",al={"milicia do povo","milicia do morro da sentinela","exercito de miguel mantoforte"}},{q="Quem lidera a Irmandade Défias em Cerro Oeste?",a="Edwin VanCleef, o antigo mestre da Guilda dos Pedreiros que supervisionou a reconstrução de Ventobravo. Após uma amarga disputa sobre pagamentos resultar em tumultos e na morte da Rainha Tiffin, VanCleef liderou seus trabalhadores até Cerro Oeste e iniciou uma insurreição armada.",al={"lider dos defias","quem lidera os defias","vancleef"}},{q="O que está escondido em Arroio da Lua?",a="Sob um celeiro despretensioso em Arroio da Lua fica a entrada para as Minas Mortas, uma extensa mina de ouro abandonada que a Irmandade Défias converteu em uma fortaleza subterrânea e estaleiro para a sua guerra contra Ventobravo.",al={"segredo de arroio da lua","o que ha nas minas mortas","mina de arroio da lua"}},{q="Por que os espantalhos mecânicos estão atacando as pessoas?",a="Construídos originalmente para cuidar das plantações e afugentar pragas, esses vigias mecânicos de colheita foram capturados e adaptados por engenhoqueiros goblins alinhados aos Défias para patrulhar os campos e assassinar quaisquer invasores.",al={"golens de colheita atacando","vigias de colheita","espantalhos malignos"}}},fp="8,337,18.502.0,27.479.0,20.427.0,24.379.1,44.289.0,52.262.0,29.269.0,45.267.0,32.226.1,51.200.0"}
P.entries["zone:wetlands"] = {n="Pantanal",s="O Pantanal é um vasto pântano envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da Baía de Baradin. Historicamente castigado por guerras dos anões e invasões órquicas, serve como uma rústica zona de amortecimento entre Altaforja e as terras do norte de Lordaeron. O porto fortificado do Porto de Menethil ergue-se como a principal tábua de salvação da Aliança em uma vastidão encharcada dominada por orcs Presa do Dragão, murlocs e gnomos.",h="O Pantanal é um vasto pântano envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da...",kw={"baía de baradin","presa do dragão","dun algaz","dun modr","grim batol","menethil","porto de menethil","ponte thandol","pantanal"},ang={["faction:Alliance"]="O Porto de Menethil serve como a principal porta de entrada em águas profundas da Aliança através do Grande Oceano, ligando os reinos do leste a postos avançados expedicionários em Kalimdor.",["profession:Mining"]="As colinas e profundezas cavernosas da Rocha de Thelgen contêm ricos veios minerais, incluindo depósitos raros de Minério de Incendicita cobiçados por mineradores e engenheiros anões.",["race:Dwarf"]="Para os anões, o Pantanal é um lugar agridoce marcado pela perda de Dun Modr, pela antiga tragédia de Grim Batol e pelo trabalho contínuo de defender a rota comercial do Rei Magni para o norte."},sec={{t="Uma Terra de Água e Ruína",b="Estendendo-se sob o imponente precipício do Dique Lapidado, o Pantanal é uma extensão fria e encharcada, envolta em névoa perpétua e céus cinzentos uniformes. Embora já tenha sido o lar de prósperos assentamentos de anões, os pântanos agora estão repletos de ruínas de pedra submersas, brejos encharcados e atoleiros traiçoeiros. Aventureiros que entram na região devem navegar por passagens estreitas, seja vindo para o norte através do desfiladeiro barricado de Dun Algaz a partir de Loch Modan, ou cruzando os imponentes arcos da Ponte Thandol a partir do Planalto Arathi."},{t="As Cicatrizes de Grim Batol",b="Os limites orientais do pântano são dominados pela presença sombria de Grim Batol, a antiga fortaleza dos Martelo Selvagem. Após sua profanação durante a Guerra dos Três Martelos, tornou-se o reduto fortificado do clã Presa do Dragão durante a Segunda Guerra. Quando a revoada dragônica vermelha se libertou do cativeiro órquico, sua vingança ardente despedaçou as forças órquicas e devastou as encostas ao redor. Hoje, dracônicos vermelhos guardam os Portões Presa do Dragão contra todos os invasores, enquanto remanescentes ferozes do clã Presa do Dragão habitam em acampamentos dispersos nas colinas, continuando a atormentar viajantes pelo pântano."},{t="Porto da Costa Oeste",b="Empoleirado na borda da Baía de Baradin, o Porto de Menethil é o coração pulsante do comércio e da logística da Aliança em Khaz Modan. Batizado em homenagem ao Rei Terenas Menethil II, este porto valoroso conecta os Reinos do Leste à distante Kalimdor por meio de navios de transporte regulares que navegam para Auberdine e Ilha Theramore. Apesar de sua importância militar estratégica e sólida arquitetura dos anões, o porto está perpetuamente ameaçado por murlocs costeiros, criaturas do pântano e saqueadores costeiros que atacam embarcações que navegam pelos canais rochosos."},{t="Fronteiras Sitiadas",b="O Pantanal é uma zona de guerra ativa em múltiplas frentes. No extremo norte, anões Ferro Negro sob o comando do bruxo Balgaras the Foul bombardearam com sabotagem a Ponte Thandol e invadiram a cidade de Dun Modr, cortando comboios de suprimentos terrestres. Enquanto isso, gnolls Mosshide correm soltos pelos pântanos centrais, ameaçando até mesmo protetores ancestrais como Rethiel, o Verdião. Entre bandos de guerra de orcs renegados, infiltrados Ferro Negro e naufrágios amaldiçoados ao longo da costa, manter o controle do pântano exige vigilância constante."}},faq={{q="Como viajo para o Pantanal a pé?",a="Aventureiros da Aliança geralmente viajam para o norte a partir de Loch Modan através do desfiladeiro da montanha de Dun Algaz. Viajantes da Horda que viajam do norte podem cruzar a Ponte Thandol a partir do Planalto Arathi. Tome cuidado, pois ambas as passagens são disputadas por forças hostis, como orcs Presa do Dragão e anões Ferro Negro.",al={"como chegar ao pantanal","caminho para o pantanal","correr para o pantanal"}},{q="Para onde vão os barcos no Porto de Menethil?",a="As docas no Porto de Menethil operam duas rotas principais de balsa para Kalimdor: um navio navega pelo Grande Oceano até Auberdine, nas margens de Costa Negra, enquanto o outro navega para o sul até a Ilha Theramore, no Pântano Vadeoso.",al={"barcos de menethil","navios do porto de menethil","para onde vai o barco no pantanal"}},{q="O que é Grim Batol e por que é guardado?",a="Grim Batol é uma antiga fortaleza dos anões abandonada após a Guerra dos Três Martelos e mais tarde ocupada pelo clã Presa do Dragão. Após a Segunda Guerra, a revoada dragônica vermelha libertada expulsou os orcs e selou a montanha. Poderosos draconianos vermelhos e dracônicos patrulham os Portões Presa do Dragão para impedir que qualquer pessoa entre nos salões amaldiçoados.",al={"por que há dragões em grim batol","dragões vermelhos de grim batol","portões presa do dragão"}},{q="O que aconteceu com Dun Modr?",a="Dun Modr era uma fortaleza nortista dos anões que guardava a Ponte Thandol. Ela foi recentemente atacada e dominada por anões Ferro Negro liderados por Balgaras the Foul. Os sobreviventes, liderados por Rhag Garmason, mantêm um acampamento sitiado nas proximidades enquanto lutam para recuperar sua cidade.",al={"quem destruiu dun modr","ruínas de dun modr","ferro negro em dun modr"}},{q="Quem é Rethiel, o Verdião?",a="Rethiel é uma antiga besta do pântano que reside na Zona Verde do Pantanal. Ele busca ajuda de viajantes para conter a maré de gnolls Mosshide agressivos e abater Fen Creepers doentes para que os pântanos possam se recuperar.",al={"zona verde","rethiel pantanal","quem é the greenwarden"}},{q="De onde vieram todos os orcs no pântano?",a="Os orcs pertencem ao clã Presa do Dragão, que originalmente se fortificou em Grim Batol durante a Segunda Guerra. Após serem devastados pela revoada dragônica vermelha libertada, os orcs sobreviventes fugiram para o pântano e colinas, onde ainda realizam ataques contra estradas e viajantes.",al={"por que há orcs no pantanal","pantanal presa do dragão","clã presa do dragão pantanal"}}},fp="8,418,24.524.0,23.601.0,22.527.0,18.503.0,40.301.0,41.216.0,41.343.0,26.268.0,31.214.0,46.277.0"}
P.entries["zone:winterspring"] = {n="Hibérnia",s="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima das florestas encantadas da Clareira da Lua e da Selva Maleva. Conhecida por seu frio congelante, ruínas ancestrais de Altaneiros e predadores de topo errantes, a região tem como ponto central o posto avançado goblin neutro de Visteterna. O local segue sendo uma terra de perigos naturais ferozes, abrigando resquícios da revoada dragônica azul enquanto enfrenta a corrupção demoníaca ao longo de suas elevações ao sul.",h="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima...",kw={"dragões azuis","garganta do sussurro sombrio","bruna covaneve","visteterna","sabre-de-gelo","chapéu-de-gelo","kel'theril","mazthoril","presamatos","hibérnia"},ang={["class:Druid"]="Localizada bem acima da Clareira da Lua, Hibérnia guarda grande importância sagrada como o local onde Malfurion Tempesfúria despertou os Druidas da Garra de seu sono ancestral durante a Terceira Guerra.",["faction:Alliance"]="Heróis da Aliança visitam com frequência Ripárion Glaciares na Pedra Sabre-de-gelo, trabalhando sem parar no frio extremo para conquistar a lealdade das prestigiosas montarias de Sabre-de-gelo de Hibérnia.",["profession:Herbalism"]="Hibérnia é o único habitat conhecido do Chapéu-de-gelo, uma erva alpina indispensável e muito visada para poções alquímicas avançadas, junto com pés espalhados de Sálvia-prata-da-montanha e raras flores de Lótus Preto.",["profession:Mining"]="Os penhascos congelados e as paredes de cavernas por todo o vale são ricos em minerais valiosos, frequentemente abrigando Pequenas Veias de Tório e Veias Ricas de Tório, além de raros depósitos de Veraprata.",["race:NightElf"]="Hibérnia está intimamente ligada à história élfica, abrigando os túmulos subterrâneos onde os Druidas da Garra repousaram por milênios, as trágicas Ruínas de Kel'Theril e raízes expostas de Nordrassil danificadas durante a Batalha do Monte Hyjal."},sec={{t="Um Reino de Gelo Perpétuo",b="Erguida milhares de metros acima da natureza ao redor, Hibérnia repousa sob o ar puro da montanha e nevascas implacáveis. Enormes raízes expostas da Árvore do Mundo, Nordrassil, cortam os montes de neve como imponentes arcos de madeira, retorcidas e deformadas durante as lutas decisivas da Terceira Guerra. Embora grande parte do norte de Kalimdor seja dominada por florestas densas e climas quentes, Hibérnia é uma terra tranquila de matas alpinas moderadas, escarpas rochosas e lagos congelados, lar de formidáveis sabres-de-gelo, quimeras, iétis e ursos invernais de pelagem espessa."},{t="Encruzilhadas e Postos Avançados",b="Chegar a este planalto elevado exige atravessar as antigas passagens esculpidas do Domínio dos Presamatos, guardadas por urscabos não corrompidos que examinam de perto quaisquer viajantes vindos da Selva Maleva ou da Clareira da Lua. No centro do vale fica Visteterna, uma próspera cidade comercial operada pelo Cartel Bondebico. Os goblins recebem aventureiros tanto da Aliança quanto da Horda de caixas abertos, atuando como um refúgio indispensável de engenharia, comércio e fogueiras acolhedoras contra o frio cortante da montanha."},{t="Velhos Fantasmas e Dracos Azuis",b="Séculos antes do surgimento dos povoados modernos, elfos ancestrais ergueram a cidade lacustre de Kel'Theril. Depois que feiticeiros Altaneiros imprudentes estilhaçaram o maldito Cristal de Zin-Malor, a loucura os consumiu, deixando fantasmas inquietos a vagar pelos pilares em ruínas e pelas águas congeladas até hoje. Mais ao sul erguem-se as alturas cavernosas de Mazthoril, a tradicional fortaleza da revoada dragônica azul em Kalimdor. Ali, a ninhada do Tecelão de Feitiços Malygos, sob a vigilância da matrona protetora Haleh, guarda as correntes arcanas e contesta ameaças locais."},{t="A Sombra Iminente da Garganta",b="A serenidade de Hibérnia é bruscamente rompida ao longo de sua fronteira mais ao sul, na Garganta do Sussurro Sombrio. Ali, forças demoníacas de elite, legiões remanescentes da Terceira Guerra, rastejam por desfiladeiros irregulares bloqueando os caminhos superiores rumo ao cume do Monte Hyjal. Enquanto isso, os urscabos Quedinverno nativos sucumbiram a corrupções vis, levando pesquisadores independentes como Bruna Covaneve a investigar a mácula que avança antes que toda a vida selvagem do vale seja consumida."}},faq={{q="Como chego a Hibérnia?",a="Os viajantes devem passar pelo Domínio dos Presamatos, uma rede subterrânea de túneis localizada no nordeste da Selva Maleva. Cruzar as cavernas pacificamente exige conquistar a confiança dos urscabos Presamatos nativos, que atacam quaisquer invasores que considerem hostis. Ao passar pela saída leste, as encostas nevadas de Hibérnia surgem imediatamente.",al={"como chegar em hibérnia","como entrar em hibérnia","entrada de hibérnia","túnel dos presamatos hibérnia"}},{q="Quem governa a cidade de Visteterna?",a="Visteterna é administrada pelo Cartel Bondebico, o conglomerado mercantil goblin. Por causa do estrito foco no lucro e da neutralidade dos goblins, tanto viajantes da Horda quanto da Aliança podem utilizar seus mestres de voo, comerciantes de reparo, cofres bancários e mercadorias, desde que os visitantes não quebrem a paz dentro dos limites da cidade.",al={"quem controla visteterna","facção de visteterna","visteterna é neutra"}},{q="O que são os fantasmas que assombram o Lago Kel'Theril?",a="São os espíritos dos Elfos Noturnos Altaneiros que habitaram a antiga cidade de Kel'Theril dez mil anos atrás. Quando seus feiticeiros mexeram no roubado Cristal de Zin-Malor, sua destruição desencadeou uma maldição catastrófica. Expedições posteriores de altos-elfos séculos depois também foram levadas à loucura, fadadas a assombrar as ruínas congeladas ao lado de seus ancestrais.",al={"fantasmas do lago kel'theril","espíritos das ruínas de kel'theril","quem está em kel'theril"}},{q="Por que os urscabos Quedinverno são agressivos?",a="Os urscabos Quedinverno sucumbiram a uma corrupção não natural que se alastrou e levou o clã à hostilidade enlouquecida. Enquanto os Presamatos próximos mantêm com firmeza a sanidade, os Quedinverno caíram sob influências sombrias, motivando pesquisadores como Bruna Covaneve a estudar a mácula e limpar seus acampamentos.",al={"por que os quedinverno são hostis","corrupção da tribo quedinverno","bruna covaneve urscabos"}},{q="O que vive dentro de Mazthoril?",a="Mazthoril é o principal ninho e santuário da revoada dragônica azul em Kalimdor. Nas profundezas de suas agulhas cavernosas, dracônicos, filhotes de elite e dracos ancestrais guardam relíquias dracônicas poderosas e segredos arcanos sob o olhar atento de Haleh, consorte do Aspecto Malygos.",al={"dragões de mazthoril","o que é mazthoril","dragões azuis em hibérnia"}},{q="O que é a Garganta do Sussurro Sombrio?",a="A Garganta do Sussurro Sombrio é um desfiladeiro traiçoeiro nos confins meridionais do vale, ocupado por poderosos demônios de elite remanescentes da Terceira Guerra. O local serve como um perímetro pesadamente vigiado ao longo das trilhas traiçoeiras que levam às alturas do Monte Hyjal.",al={"demônios da garganta do sussurro sombrio","o que há na garganta do sussurro sombrio","portão de hyjal hibérnia"}},{q="É possível treinar ou domar sabres-de-gelo aqui?",a="Na Pedra Sabre-de-gelo, no extremo norte do vale, o Elfo Noturno Ripárion Glaciares cuida dos felinos brancos nativos. Aventureiros que o ajudam a conseguir suprimentos e a proteger o bando podem provar seu valor para aprender os segredos da criação e montaria de um Sabre-de-gelo.",al={"montaria sabre-de-gelo","ripárion glaciares sabre-de-gelo","como obter sabre-de-gelo"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="Ilha de Zefras",s="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar. Ela serve como o lar ancestral inicial dos Skyborne, cuja sociedade agora enfrenta uma crise existencial à medida que a magia que sustenta a ilha se desgasta continuamente. Com o contato cortado com os reinos celestes vizinhos, seus habitantes lutam contra o colapso elemental e a chegada de refugiados.",h="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar.",kw={"aeronaves","anvilas","plano elemental","siroccas","skyborne","muralha celeste","valanaar","windstones","zefras"},ang={["class:Shaman"]="Existindo diretamente dentro do Plano Elemental do ar, a Ilha de Zefras exemplifica o que acontece com terras elementais quando os espíritos que as equilibram desaparecem de repente.",["race:Skyborne"]="A Ilha de Zefras é o seu lar ancestral e ponto de partida, embora sua beleza remanescente mascare uma crise urgente de terreno em colapso e poder elemental minguante."},sec={{t="Um Reino nas Alturas",b="A Ilha de Zefras é uma massa de terra isolada à deriva nos ventos eternos da Muralha Celeste. Por gerações, os Skyborne viveram aqui ao lado de elementais do ar nativos que ajudavam a preservar as correntes mágicas que mantinham a ilha no alto. No entanto, vários séculos atrás, esses guardiões elementais desapareceram por completo. Privados de sua presença e tutela, os encantamentos latentes que sustentavam a terra começaram a falhar lentamente, fazendo com que Zefras se frature e se desestabilize aos poucos."},{t="Horizontes Interrompidos",b="Zefras não era o único santuário habitado pelos Skyborne dentro do Plano Elemental. Ilhas irmãs conhecidas como Anvilas e Siroccas também flutuavam pela Muralha Celeste, mas as comunicações entre elas cessaram após o desaparecimento dos elementais. Recentemente, refugiados dessas massas de terra vizinhas em ruínas conseguiram chegar a Zefras em busca de segurança, trazendo notícias sombrias de que as outras ilhas estão se desintegrando de vez sob seus pés."},{t="Limiar para Azeroth",b="Com sua própria massa de terra em lenta decadência, os Skyborne de Zefras começaram a olhar além das fronteiras da Muralha Celeste, em direção a Azeroth. Dos ancoradouros celestes de Valanaar, aeronaves agora partem para estabelecer raras conexões vitais com o reino mortal. Essas viagens conectam o domínio aéreo diretamente a pontos em Azeroth, incluindo os arredores de Dalaran nas Montanhas de Alterac e o Platô do Vigia dos Céus em Mulgore."}},faq={{q="Onde fica a Ilha de Zefras?",a="A Ilha de Zefras está situada dentro da Muralha Celeste, o Plano Elemental do ar, em vez de na superfície de Azeroth. Ela flutua em meio às nuvens perpétuas e às correntes de vento deste domínio etéreo.",al={"localização da ilha de zefras","onde fica zefras","em qual plano fica zefras"}},{q="Por que a Ilha de Zefras está se desfazendo?",a="A ilha dependia da presença de elementais do ar nativos que outrora coexistiam com os Skyborne. Vários séculos atrás, esses elementais desapareceram, deixando as fundações mágicas que ancoram e preservam a terra voadora enfraquecerem e se degradarem lentamente ao longo do tempo.",al={"por que zefras está colapsando","destruição da ilha de zefras","ilha moribunda"}},{q="O que são Anvilas e Siroccas?",a="São ilhas voadoras vizinhas na Muralha Celeste, também povoadas pelos Skyborne. A Ilha de Zefras perdeu a comunicação com ambas quando os elementais desapareceram, e refugiados em fuga agora relatam que tanto Anvilas quanto Siroccas estão colapsando no esquecimento.",al={"anvilas","siroccas","outras ilhas dos skyborne"}},{q="Como as pessoas viajam entre a Ilha de Zefras e Azeroth?",a="Os Skyborne operam ancoradouros celestes no assentamento de Valanaar. Aeronaves partem dessas docas através da fronteira planar em direção a Azeroth, pousando perto de Dalaran nas Montanhas de Alterac e no Platô do Vigia dos Céus em Mulgore.",al={"como sair de zefras","aeronaves de zefras","viajar para azeroth"}},{q="Quem são os Skyborne?",a="Os Skyborne são os habitantes que vivem na Ilha de Zefras e em seus reinos celestes irmãos. Tendo habitado a Muralha Celeste por gerações, eles agora enfrentam a lenta destruição de sua terra natal voadora à medida que sua magia de sustentação se dissipa.",al={"raça skyborne","quem vive em zefras"}},{q="Quem vive na Ilha de Zefras além dos Skyborne?",a="Além de aldeias pacíficas e refugiados visitantes, a ilha é assolada por bandidos locais, noctigarras que vivem em cavernas e feras que habitam áreas como o Covil dos Guinchotes e a Caverna dos Noctigarra.",al={"habitantes de zefras","inimigos em zefras"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
